CREATE OR REPLACE FUNCTION auth.uid()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$function$

CREATE OR REPLACE FUNCTION private.admin_channel_states()
 RETURNS TABLE(workspace_id uuid, channel_id uuid, state text, last_ok_at timestamp with time zone, last_error text, last_run_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select c.workspace_id, c.id,
         case
           when c.paused_at is not null then 'paused'
           when exists (select 1 from public.jobs j
                         where j.workspace_id = c.workspace_id and j.channel_id = c.id
                           and j.type = 'discover' and j.status in ('queued', 'running'))
             then 'cataloguing'
           when exists (select 1 from public.jobs j
                         where j.workspace_id = c.workspace_id and j.channel_id = c.id
                           and j.type = 'collect' and j.status in ('queued', 'running'))
             then 'collecting'
           when lr.status = 'failed' then 'failing'
           when c.catalogued_at is null then 'new'
           when not exists (select 1 from public.video_selections s
                             where s.workspace_id = c.workspace_id and s.channel_id = c.id)
             then 'waiting'
           when lc.ok_at is null or lc.ok_at < now() - interval '48 hours' then 'stale'
           else 'healthy'
         end,
         lc.ok_at,
         case when lr.status = 'failed' then lr.error_code end,
         lr.started_at
    from public.channels c
    left join lateral (
      select sr.status, sr.error_code, sr.started_at
        from public.sync_runs sr
       where sr.channel_id = c.id
       order by sr.started_at desc
       limit 1) lr on true
    left join lateral (
      select coalesce(sr.ended_at, sr.started_at) as ok_at
        from public.sync_runs sr
       where sr.channel_id = c.id
         and sr.mode = 'collect'
         and sr.status in ('succeeded', 'partial')
       order by sr.started_at desc
       limit 1) lc on true
$function$

CREATE OR REPLACE FUNCTION private.adopt_channel_catalogue(w uuid, c uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ch public.channels;
  adopted_count int := 0;
begin
  select * into ch from public.channels
   where workspace_id = w and id = c;
  if ch.id is null then return 0; end if;

  insert into public.videos (
    workspace_id, channel_id, platform, external_video_id, title, kind,
    published_at, duration_sec, thumbnail_url, reported_comment_count,
    reported_comment_count_at, comments_state, view_count, like_count, favorite_count,
    tags, description, category_id, catalogued_at, last_observed_at,
    field_provenance
  )
  select distinct on (v.external_video_id)
    w, c, v.platform, v.external_video_id, v.title, v.kind,
    v.published_at, v.duration_sec, v.thumbnail_url, v.reported_comment_count,
    v.reported_comment_count_at, v.comments_state, v.view_count, v.like_count, v.favorite_count,
    v.tags, v.description, v.category_id, v.catalogued_at, now(),
    coalesce(v.field_provenance, '{}'::jsonb)
  from public.channels donor_ch
  join public.videos v
    on v.workspace_id = donor_ch.workspace_id and v.channel_id = donor_ch.id
  where donor_ch.platform = ch.platform
    and donor_ch.external_channel_id = ch.external_channel_id
    and donor_ch.workspace_id <> w
    and donor_ch.status <> 'disconnected'
  order by v.external_video_id, donor_ch.id, v.id
  on conflict (workspace_id, platform, external_video_id) do update set
    title = case when excluded.title <> excluded.external_video_id
                 then excluded.title else public.videos.title end,
    kind = excluded.kind,
    thumbnail_url = coalesce(excluded.thumbnail_url, public.videos.thumbnail_url),
    reported_comment_count = coalesce(excluded.reported_comment_count, public.videos.reported_comment_count),
    reported_comment_count_at = coalesce(excluded.reported_comment_count_at, public.videos.reported_comment_count_at),
    comments_state = excluded.comments_state,
    view_count = coalesce(excluded.view_count, public.videos.view_count),
    like_count = coalesce(excluded.like_count, public.videos.like_count),
    favorite_count = coalesce(excluded.favorite_count, public.videos.favorite_count),
    tags = case when excluded.tags <> '{}'::text[] then excluded.tags else public.videos.tags end,
    description = coalesce(nullif(excluded.description, ''), public.videos.description),
    category_id = coalesce(excluded.category_id, public.videos.category_id),
    last_observed_at = now();

  get diagnostics adopted_count = row_count;
  if adopted_count > 0 and ch.catalogued_at is null then
    update public.channels set catalogued_at = now()
     where workspace_id = w and id = c;
  end if;
  return adopted_count;
end $function$

CREATE OR REPLACE FUNCTION private.adopt_channel_content(w uuid, c uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ch public.channels;
  target_video record;
  adopted jsonb;
  vids_adopted int := 0;
  comments_adopted int := 0;
begin
  select * into ch from public.channels
   where workspace_id = w and id = c;
  if ch.id is null then
    return jsonb_build_object('videos', 0, 'comments', 0, 'sentiment', 0, 'topics', 0);
  end if;

  vids_adopted := private.adopt_channel_catalogue(w, c);
  for target_video in
    select v.id from public.videos v
     where v.workspace_id = w and v.channel_id = c
     order by v.id
  loop
    adopted := private.adopt_video_comments_and_predictions(w, target_video.id);
    comments_adopted := comments_adopted + coalesce((adopted->>'comments')::int, 0);
  end loop;

  return jsonb_build_object(
    'videos', vids_adopted, 'comments', comments_adopted,
    'sentiment', 0, 'topics', 0
  );
end $function$

CREATE OR REPLACE FUNCTION private.adopt_first_analysis()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.channels c
     set active_analysis_key = k.analysis_key
    from (
      select v.channel_id, n.workspace_id, min(n.analysis_key) as analysis_key
        from new_predictions n
        join public.comments cm
          on cm.workspace_id = n.workspace_id and cm.id = n.comment_id
        join public.videos v
          on v.workspace_id = n.workspace_id and v.id = cm.video_id
       where n.status = 'succeeded'
       group by v.channel_id, n.workspace_id
      -- One analysis per adoption. A batch carrying two different keys for the
      -- same channel is ambiguous, and picking one would be a coin toss that
      -- decides what every label on the dashboard means.
      having count(distinct n.analysis_key) = 1
    ) k
   where c.workspace_id = k.workspace_id
     and c.id = k.channel_id
     and c.active_analysis_key is null;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.adopt_first_topic_classification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.workspaces w
     set active_topic_key = k.classification_key
    from (
      select n.workspace_id, min(n.classification_key) as classification_key
        from new_predictions n
       where n.status = 'succeeded'
       group by n.workspace_id
      having count(distinct n.classification_key) = 1
    ) k
   where w.id = k.workspace_id
     and w.active_topic_key is null;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.adopt_video_comments_and_predictions(w uuid, v uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  vid public.videos;
  donor_vid uuid;
  donor_ws uuid;
  donor_complete boolean := false;
  adopted_comments int := 0;
  total_stored int := 0;
begin
  select * into vid from public.videos
   where workspace_id = w and id = v;
  if vid.id is null then
    return jsonb_build_object('comments', 0, 'sentiment', 0, 'topics', 0);
  end if;

  select donor_v.id, donor_v.workspace_id,
         coalesce(donor_s.last_outcome in ('exhausted', 'unchanged'), false)
    into donor_vid, donor_ws, donor_complete
  from public.channels target_ch
  join public.channels donor_ch
    on donor_ch.platform = target_ch.platform
   and donor_ch.external_channel_id = target_ch.external_channel_id
   and donor_ch.workspace_id <> w
   and donor_ch.status <> 'disconnected'
  join public.videos donor_v
    on donor_v.workspace_id = donor_ch.workspace_id
   and donor_v.channel_id = donor_ch.id
   and donor_v.platform = vid.platform
   and donor_v.external_video_id = vid.external_video_id
  join public.comments donor_comment
    on donor_comment.workspace_id = donor_v.workspace_id
   and donor_comment.video_id = donor_v.id
  left join public.video_selections donor_s
    on donor_s.workspace_id = donor_v.workspace_id
   and donor_s.video_id = donor_v.id
  where target_ch.workspace_id = w and target_ch.id = vid.channel_id
  order by donor_ch.id, donor_v.id
  limit 1;

  if donor_vid is null then
    return jsonb_build_object('comments', 0, 'sentiment', 0, 'topics', 0);
  end if;

  -- Platform collection is the explicit allowlist below. external_import and
  -- sanitized_fixture are excluded, and file_upload provenance is refused even
  -- if a malformed row carries an allowed source. New collectors must opt in.
  insert into public.comments (
    workspace_id, video_id, platform, external_comment_id, external_parent_id,
    is_reply, parent_source, author_channel_id, author_name, text_raw, text_plain,
    content_hash, published_time_raw, published_at, timestamp_precision,
    likes_raw, likes_value, source, field_provenance,
    author_profile_image_url, author_channel_url, reply_count, updated_at
  )
  select
    w, v, c.platform, c.external_comment_id, c.external_parent_id,
    c.is_reply, c.parent_source, c.author_channel_id, c.author_name, c.text_raw, c.text_plain,
    c.content_hash, c.published_time_raw, c.published_at, c.timestamp_precision,
    c.likes_raw, c.likes_value, c.source, c.field_provenance,
    c.author_profile_image_url, c.author_channel_url, coalesce(c.reply_count, 0), c.updated_at
  from public.comments c
  where c.workspace_id = donor_ws
    and c.video_id = donor_vid
    and c.source in (
      'youtube_data_api_public', 'youtube_oauth', 'telegram_mtproto',
      'x_api', 'tiktok_display_api', 'apify', 'brightdata'
    )
    and coalesce(c.field_provenance->>'source', '') <> 'file_upload'
  on conflict (workspace_id, platform, external_comment_id) do nothing;

  get diagnostics adopted_comments = row_count;

  if donor_complete and adopted_comments > 0 then
    select count(*)::int into total_stored from public.comments
     where workspace_id = w and video_id = v;
    update public.video_selections
       set last_seen_comment_count = total_stored,
           last_collected_at = (select max(last_seen_at) from public.comments
                                where workspace_id = w and video_id = v),
           last_outcome = 'exhausted',
           next_check_at = now() + make_interval(
             mins => coalesce(private.plan_limit(w, 'live_interval'), 1440))
     where workspace_id = w and video_id = v;
  end if;

  return jsonb_build_object(
    'comments', adopted_comments, 'sentiment', 0, 'topics', 0
  );
end $function$

CREATE OR REPLACE FUNCTION private.analysis_remaining(w uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sub record; begin
  select s.period_start, pl.analysis_units into sub
    from public.subscriptions s join public.plans pl on pl.key = s.plan_key
   where s.workspace_id = private.billing_root(w) and private.subscription_open(s);
  if not found then raise exception 'no_active_plan' using errcode='53400'; end if;
  if sub.analysis_units is null or sub.analysis_units >= 2147483647 then return null; end if;
  return greatest(0::bigint, sub.analysis_units::bigint + private.granted_units(w, 'comment_analysis')
                     - private.used_units(w, 'comment_analysis', sub.period_start));
end $function$

CREATE OR REPLACE FUNCTION private.apply_billing_event(event_id text, event_type text, occurred_at timestamp with time zone, w uuid, plan text, billing_interval text, period_start timestamp with time zone, period_end timestamp with time zone, status text, cancel_at_period_end boolean, provider_ref text, customer_ref text, payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare root uuid; last_seen timestamptz; live record; begin
  root := coalesce(private.billing_root(w), w);
  -- One root's events serialise on this lock for the rest of the transaction
  -- (see 20260917050000 for why): a duplicate beside its original waits and
  -- reads 'duplicate', an older event waits and reads 'stale'.
  perform pg_advisory_xact_lock(hashtextextended(root::text, 0));
  if exists (select 1 from private.billing_events e where e.event_id = apply_billing_event.event_id) then
    return 'duplicate'; end if;
  select max(e.occurred_at) into last_seen from private.billing_events e
   where e.workspace_id = root and e.outcome = 'applied' and e.event_type like 'subscription.%';
  if last_seen is not null and occurred_at < last_seen then
    insert into private.billing_events(event_id, event_type, occurred_at, workspace_id, applied_at, outcome, payload)
    values (event_id, event_type, occurred_at, root, now(), 'stale', payload);
    return 'stale';
  end if;
  select s.provider, s.status, s.provider_ref into live from public.subscriptions s where s.workspace_id = root;
  if found and live.provider = 'paddle' and live.status in ('active','past_due')
     and live.provider_ref <> apply_billing_event.provider_ref then
    insert into private.billing_events(event_id, event_type, occurred_at, workspace_id, applied_at, outcome, payload)
    values (event_id, event_type, occurred_at, root, now(), 'conflict', payload);
    return 'conflict';
  end if;
  if status in ('cancelled','paused') then
    insert into public.subscriptions(workspace_id, plan_key, status, period_start, period_end, provider, provider_ref,
                                     provider_customer_ref, billing_interval, cancel_at_period_end)
    values (root, 'free', 'active', now(), now() + interval '100 years', null, null, null, null, false)
    on conflict (workspace_id) do update set
      plan_key = 'free', status = 'active', provider = null, provider_ref = null,
      provider_customer_ref = null, billing_interval = null, cancel_at_period_end = false,
      period_start = now(), period_end = now() + interval '100 years';
    update public.subscriptions s
       set plan_key = 'free', status = 'active', provider = null, provider_ref = null,
           provider_customer_ref = null, billing_interval = null, cancel_at_period_end = false,
           period_start = now(), period_end = now() + interval '100 years'
     where s.billing_workspace_id = root;
    insert into public.audit_events(workspace_id, actor_id, action, target_type, target_id)
    values (w, null, 'plan_paddle_' || replace(event_type, 'subscription.', ''), 'plan', 'free');
    insert into private.billing_events(event_id, event_type, occurred_at, workspace_id, applied_at, outcome, payload)
    values (event_id, event_type, occurred_at, root, now(), 'applied', payload);
    return 'applied';
  end if;
  insert into public.subscriptions(workspace_id, plan_key, status, period_start, period_end, provider, provider_ref,
                                   provider_customer_ref, billing_interval, cancel_at_period_end)
  values (root, plan, status, period_start, period_end, 'paddle', provider_ref, customer_ref, billing_interval, cancel_at_period_end)
  on conflict (workspace_id) do update set
    plan_key = excluded.plan_key, status = excluded.status,
    period_start = excluded.period_start, period_end = excluded.period_end,
    provider = 'paddle', provider_ref = excluded.provider_ref, provider_customer_ref = excluded.provider_customer_ref,
    billing_interval = excluded.billing_interval, cancel_at_period_end = excluded.cancel_at_period_end;
  -- Every client workspace billing through root copied its row from the root
  -- at creation (private.create_workspace_impl); keep the copies in step.
  update public.subscriptions s
     set plan_key = apply_billing_event.plan, status = apply_billing_event.status,
         period_start = apply_billing_event.period_start, period_end = apply_billing_event.period_end,
         provider = 'paddle', provider_ref = apply_billing_event.provider_ref,
         provider_customer_ref = apply_billing_event.customer_ref,
         billing_interval = apply_billing_event.billing_interval,
         cancel_at_period_end = apply_billing_event.cancel_at_period_end
   where s.billing_workspace_id = root;
  insert into public.audit_events(workspace_id, actor_id, action, target_type, target_id)
  values (w, null, 'plan_paddle_' || replace(event_type, 'subscription.', ''), 'plan', plan);
  insert into private.billing_events(event_id, event_type, occurred_at, workspace_id, applied_at, outcome, payload)
  values (event_id, event_type, occurred_at, root, now(), 'applied', payload);
  return 'applied';
end $function$

CREATE OR REPLACE FUNCTION private.apply_pack_event(event_id text, occurred_at timestamp with time zone, w uuid, kind text, units integer, provider_ref text, payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare root uuid; begin
  root := coalesce(private.billing_root(w), w);
  -- Same lock as apply_billing_event, for the same reason: a retried pack
  -- delivery beside its original must read 'duplicate', not grant and audit
  -- twice. grant_units is unique on (source, provider_ref) regardless.
  perform pg_advisory_xact_lock(hashtextextended(root::text, 0));
  if exists (select 1 from private.billing_events e where e.event_id = apply_pack_event.event_id) then
    return 'duplicate'; end if;
  perform private.grant_units(w, kind, units, 'paddle', provider_ref);
  insert into public.audit_events(workspace_id, actor_id, action, target_type, target_id)
  values (w, null, 'pack_paddle', 'usage_grant', kind || ':' || units);
  insert into private.billing_events(event_id, event_type, occurred_at, workspace_id, applied_at, outcome, payload)
  values (event_id, 'transaction.completed', occurred_at, root, now(), 'applied', payload);
  return 'applied';
end $function$

CREATE OR REPLACE FUNCTION private.audit_plan_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new is distinct from old then
    insert into public.audit_events(workspace_id, actor_id, action, target_type, target_id)
    values (null, auth.uid(), 'plan_updated', 'plan', new.key);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.auto_select_after_catalogue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  picked integer;
begin
  -- The selection is a convenience on top of the job's own outcome: a fault
  -- here must not undo the finished run. The scheduler tries again within
  -- the hour.
  begin
    -- Two statements: `has_due_videos` is stable, so within the statement
    -- that selects it would not see the new selections.
    picked := private.auto_select_videos(new.workspace_id, new.channel_id);
    if picked > 0 and private.has_due_videos(new.workspace_id, new.channel_id) then
      perform private.enqueue_scheduled(new.workspace_id, new.channel_id, 'collect');
    end if;
  exception when others then
    raise warning 'auto_select_after_catalogue(%, %): %',
      new.workspace_id, new.channel_id, sqlerrm;
  end;
  return null;
end $function$

CREATE OR REPLACE FUNCTION private.auto_select_videos(w uuid, c uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  cfg private.channel_auto_selection;
  remaining bigint;
  room integer;
  picked uuid[];
  v uuid;
begin
  select * into cfg from private.channel_auto_selection
   where workspace_id = w and channel_id = c
   for update skip locked;
  if not found then return 0; end if;

  if not exists (select 1 from public.channels
                  where workspace_id = w and id = c and catalogued_at is not null
                    and paused_at is null)
     or exists (select 1 from public.jobs
                 where workspace_id = w and channel_id = c and type = 'discover'
                   and status in ('queued', 'running')) then
    return 0;
  end if;

  remaining := private.analysis_remaining(w);
  if remaining is not null and remaining <= 0 then return 0; end if;

  if cfg.initial_done_at is null then
    select coalesce(array_agg(x.id), '{}') into picked from (
      select vd.id from public.videos vd
       where vd.workspace_id = w and vd.channel_id = c
         and vd.kind in ('video', 'short', 'stream')
         and vd.comments_state <> 'disabled'
         and not exists (select 1 from public.video_selections s
                          where s.workspace_id = w and s.video_id = vd.id)
       order by vd.published_at desc nulls last, vd.id
       limit cfg.initial_count) x;
    update private.channel_auto_selection
       set initial_done_at = now(),
           watermark = coalesce(
             (select max(vd.published_at) from public.videos vd
               where vd.workspace_id = w and vd.channel_id = c), now())
     where workspace_id = w and channel_id = c;
  else
    room := cfg.daily_cap - (
      select count(*) from private.auto_selected_videos a
       where a.workspace_id = w and a.channel_id = c and not a.initial
         and a.selected_at > now() - interval '24 hours');
    if room <= 0 then return 0; end if;
    select coalesce(array_agg(x.id), '{}') into picked from (
      select vd.id from public.videos vd
       where vd.workspace_id = w and vd.channel_id = c
         and vd.kind in ('video', 'short', 'stream')
         and vd.comments_state <> 'disabled'
         and vd.published_at > cfg.watermark
         and not exists (select 1 from public.video_selections s
                          where s.workspace_id = w and s.video_id = vd.id)
         and not exists (select 1 from private.auto_selected_videos a
                          where a.workspace_id = w and a.video_id = vd.id)
       order by vd.published_at desc, vd.id
       limit room) x;
  end if;

  foreach v in array picked loop
    insert into public.video_selections(workspace_id, channel_id, video_id, selected_by)
    values (w, c, v, cfg.created_by)
    on conflict (workspace_id, video_id) do nothing;
    insert into private.auto_selected_videos(workspace_id, video_id, channel_id, initial)
    values (w, v, c, cfg.initial_done_at is null)
    on conflict (workspace_id, video_id) do nothing;
    perform private.adopt_video_comments_and_predictions(w, v);
  end loop;
  return cardinality(picked);
end $function$

CREATE OR REPLACE FUNCTION private.backfill_remaining(w uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sub record; begin
  select s.period_start, pl.backfill_units into sub
    from public.subscriptions s join public.plans pl on pl.key = s.plan_key
   where s.workspace_id = private.billing_root(w) and private.subscription_open(s);
  if not found then raise exception 'no_active_plan' using errcode='53400'; end if;
  if sub.backfill_units is null or sub.backfill_units >= 2147483647 then return null; end if;
  return greatest(0::bigint, sub.backfill_units::bigint + private.granted_units(w, 'historical_backfill')
                     - private.used_units(w, 'historical_backfill', sub.period_start));
end $function$

CREATE OR REPLACE FUNCTION private.backoff_after(attempts integer)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select now() + least(interval '10 minutes' * power(2, least(attempts, 8)), interval '24 hours');
$function$

CREATE OR REPLACE FUNCTION private.billing_root(w uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(s.billing_workspace_id, s.workspace_id) from public.subscriptions s where s.workspace_id = w
$function$

CREATE OR REPLACE FUNCTION private.billing_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n int; begin
  with roots as (
    select s.workspace_id from public.subscriptions s
     where s.billing_workspace_id is null
       and s.status = 'past_due' and s.period_end + interval '7 days' < now()),
  dropped as (
    update public.subscriptions s
       set plan_key = 'free', status = 'active', provider = null, provider_ref = null,
           provider_customer_ref = null, billing_interval = null, cancel_at_period_end = false,
           period_start = now(), period_end = now() + interval '100 years'
     where s.workspace_id in (select workspace_id from roots)
        or s.billing_workspace_id in (select workspace_id from roots)
     returning s.workspace_id),
  audited as (
    insert into public.audit_events(workspace_id, actor_id, action, target_type, target_id)
    select r.workspace_id, null, 'plan_dropped', 'plan', 'free' from roots r
    where exists (select 1 from dropped d where d.workspace_id = r.workspace_id)
    returning workspace_id)
  select count(*) into n from audited;
  return n;
end $function$

CREATE OR REPLACE FUNCTION private.blocked_until(w uuid, kind text, reason text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  remaining bigint;
  plan_reset timestamptz;
begin
  if reason = 'rate_limited' then
    return now() + interval '1 hour';
  end if;
  if reason is null or reason not ilike '%quota%' then
    return null;
  end if;

  begin
    remaining := case when kind = 'analyse' then private.topic_units_remaining(w)
                      else private.analysis_remaining(w) end;
  exception when sqlstate '53400' then
    -- no_active_plan: there are no plan units to have spent.
    remaining := null;
  end;

  if remaining is not null and remaining <= 0 then
    select s.period_end into plan_reset
      from public.subscriptions s
     where s.workspace_id = private.billing_root(w);
    if plan_reset is not null and plan_reset > now()
       and plan_reset <= now() + interval '366 days' then
      return plan_reset;
    end if;
  end if;

  return private.source_quota_resets_at();
end $function$

CREATE OR REPLACE FUNCTION private.bootstrap_personal_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid; begin
  insert into public.workspaces(name,created_by) values('مساحة العمل الشخصية',new.id) returning id into w;
  insert into public.memberships values(w,new.id,'workspace_owner');
  insert into public.clients(workspace_id,name) values(w,'مساحة العمل الشخصية');
  perform private.grant_default_plan(w);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.budget_entry(kind text, allowance bigint, used bigint, granted bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'event_type', kind,
    'allowance', case when allowance is null or allowance < 0 or allowance = 2147483647 then -1 else (allowance + granted) end,
    'granted', granted,
    'used', used,
    'remaining', case when allowance is null or allowance < 0 or allowance = 2147483647 then -1 else greatest((allowance + granted) - used, 0::bigint) end
  );
$function$

CREATE OR REPLACE FUNCTION private.build_admin_digest()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
  today date := (now() at time zone 'UTC')::date;
begin
  with st as (select * from private.admin_channel_states()),
  -- One row per YouTube channel, through the copy with the most judged
  -- comments, as the comparison page shows it.
  weeks as (
    select x.workspace_id, x.channel_id,
           coalesce(sum(x.positive) filter (where x.day > today - 7), 0) as wp,
           coalesce(sum(x.negative) filter (where x.day > today - 7), 0) as wn,
           coalesce(sum(x.positive) filter (where x.day > today - 14 and x.day <= today - 7), 0) as pp,
           coalesce(sum(x.negative) filter (where x.day > today - 14 and x.day <= today - 7), 0) as pn,
           sum(x.positive + x.negative) as polar
      from private.channel_compare_cells x
     group by x.workspace_id, x.channel_id
  ),
  movers as (
    select distinct on (c.platform, c.external_channel_id)
           c.id, c.workspace_id, c.title, c.handle,
           round(((w.wp - w.wn)::numeric / (w.wp + w.wn)
                - (w.pp - w.pn)::numeric / (w.pp + w.pn)) * 100, 1) as change
      from weeks w
      join public.channels c on c.workspace_id = w.workspace_id and c.id = w.channel_id
     where w.wp + w.wn >= 20 and w.pp + w.pn >= 20
     order by c.platform, c.external_channel_id, w.polar desc, c.id
  )
  select jsonb_build_object(
    'states', jsonb_build_object(
      'paused', (select count(*) from st where state = 'paused'),
      'cataloguing', (select count(*) from st where state = 'cataloguing'),
      'collecting', (select count(*) from st where state = 'collecting'),
      'failing', (select count(*) from st where state = 'failing'),
      'new', (select count(*) from st where state = 'new'),
      'waiting', (select count(*) from st where state = 'waiting'),
      'stale', (select count(*) from st where state = 'stale'),
      'healthy', (select count(*) from st where state = 'healthy')),
    'failing', coalesce((
      select jsonb_agg(jsonb_build_object(
               'channel_id', s.channel_id,
               'title', c.title,
               'handle', c.handle,
               'error_code', s.last_error)
             order by c.title nulls last, s.channel_id)
        from st s
        join public.channels c on c.id = s.channel_id
       where s.state = 'failing'), '[]'::jsonb),
    'comments', (select coalesce(sum(total), 0) from private.video_comment_stats),
    'analysed', (select coalesce(sum(analysed), 0) from private.video_comment_stats),
    'failed_runs', (select count(*) from public.sync_runs
                     where status = 'failed' and started_at >= now() - interval '24 hours'),
    'imported', (select count(*) from public.audit_events
                  where action = 'channel_imported' and created_at >= now() - interval '24 hours'),
    'movers', coalesce((
      select jsonb_agg(jsonb_build_object(
               'channel_id', m.id,
               'title', m.title,
               'handle', m.handle,
               'change', m.change)
             order by abs(m.change) desc, m.id)
        from (select * from movers where change <> 0
               order by abs(change) desc, id limit 3) m), '[]'::jsonb))
  into result;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.cancel_job_impl(w uuid, j uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current text; begin
  if not private.has_role(w, array['workspace_owner','analyst']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  select status into current from public.jobs where workspace_id=w and id=j;
  if not found then raise exception 'unknown_job' using errcode='42704'; end if;
  -- Only work that has not started. A finished job is history, and history is
  -- not cancellable.
  if current <> 'queued' then
    raise exception 'job_not_cancellable' using errcode='53400'; end if;
  update public.jobs set status='cancelled', error_code='cancelled_by_operator'
   where workspace_id=w and id=j;
end $function$

CREATE OR REPLACE FUNCTION private.catalogue_interval_or_default(w uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    (select pl.catalogue_interval_minutes
       from public.subscriptions s
       join public.plans pl on pl.key = s.plan_key
      where s.workspace_id = private.billing_root(w)
        and s.status in ('active', 'past_due')),
    1440)
$function$

CREATE OR REPLACE FUNCTION private.channel_compare_step()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  u record;
  have_unit boolean;
  failure text;
begin
  -- The triggers' marks become dirty channels; new channels join dirty.
  with marks as (
    delete from private.channel_compare_dirty d
    returning d.workspace_id, d.marked_at
  ),
  per_ws as (
    select m.workspace_id, min(m.marked_at) as since from marks m group by m.workspace_id
  )
  insert into private.channel_compare_units as un(workspace_id, channel_id, dirty_since)
  select c.workspace_id, c.id, p.since
    from per_ws p
    join public.channels c on c.workspace_id = p.workspace_id
  on conflict (workspace_id, channel_id) do update
    set dirty_since = least(coalesce(un.dirty_since, excluded.dirty_since), excluded.dirty_since);

  insert into private.channel_compare_units(workspace_id, channel_id, dirty_since)
  select c.workspace_id, c.id, now()
    from public.channels c
   where not exists (select 1 from private.channel_compare_units x
                      where x.workspace_id = c.workspace_id and x.channel_id = c.id);

  -- Never counted first, then the longest waiting. A unit whose mark is
  -- fresh waits five minutes so a burst of verdicts is counted once.
  select x.workspace_id, x.channel_id, x.attempts into u
    from private.channel_compare_units x
   where x.dirty_since is not null
     and (x.next_attempt_at is null or x.next_attempt_at <= now())
     and (x.refreshed_at is null or x.dirty_since <= now() - interval '5 minutes')
   order by x.attempts, (x.refreshed_at is not null), x.dirty_since, x.workspace_id, x.channel_id
   limit 1;
  have_unit := found;

  failure := private.unseen_job_failure('channel-compare-step');
  if failure is not null then
    if have_unit then
      update private.channel_compare_units
         set attempts = attempts + 1,
             next_attempt_at = private.backoff_after(attempts),
             last_error = failure,
             last_error_at = now()
       where workspace_id = u.workspace_id and channel_id = u.channel_id;
    end if;
    return 'failure recorded';
  end if;

  if not have_unit then
    return 'idle';
  end if;

  begin
    perform private.refresh_channel_compare_channel(u.workspace_id, u.channel_id);
  exception when others then
    update private.channel_compare_units
       set attempts = attempts + 1,
           next_attempt_at = private.backoff_after(attempts),
           last_error = left(sqlerrm, 300),
           last_error_at = now()
     where workspace_id = u.workspace_id and channel_id = u.channel_id;
    return 'error recorded';
  end;
  return 'counted';
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_job(w uuid)
 RETURNS SETOF jobs
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  return query select * from private.claim_job(w, null::text[]);
end $function$

CREATE OR REPLACE FUNCTION private.claim_job(w uuid, job_types text[])
 RETURNS SETOF jobs
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare claimed public.jobs;
begin
  if w is null then
    insert into public.worker_seen(workspace_id, last_seen_at)
    select ws.id, now() from public.workspaces ws
    on conflict (workspace_id) do update set last_seen_at = now();
  else
    insert into public.worker_seen(workspace_id, last_seen_at)
    values (w, now())
    on conflict (workspace_id) do update set last_seen_at = now();
  end if;

  update public.jobs set
      status = 'failed',
      error_code = case
        when reclaims >= 20
          then 'lease_thrashing:' || reclaims::text
        else 'retry_exhausted:' || coalesce(last_error, 'no_error_recorded')
      end,
      lease_token = null,
      lease_expires_at = null
   where (w is null or workspace_id = w)
     and status in ('queued', 'running')
     and (attempt >= 3 or reclaims >= 20)
     and (lease_expires_at is null or lease_expires_at <= now());

  update public.jobs j set
      status = 'running',
      attempt = j.attempt + case when j.status = 'queued' then 1 else 0 end,
      reclaims = j.reclaims + case
        when j.status = 'running' and j.heartbeats > 0 then 1 else 0 end,
      not_before = case
        when j.status = 'running' and j.heartbeats > 0 and j.reclaims >= 1
          then now() + least(interval '30 seconds' * (2 ^ least(j.reclaims, 5)),
                             interval '10 minutes')
        else j.not_before end,
      heartbeats = 0,
      lease_token = gen_random_uuid(),
      lease_expires_at = now() + interval '5 minutes'
   where j.id = (
     select q.id from public.jobs q
      where (w is null or q.workspace_id = w)
        and (job_types is null or cardinality(job_types) = 0
             or q.type = any(job_types))
        and q.attempt < 3
        and q.reclaims < 20
        and q.not_before <= now()
        and (q.status = 'queued'
             or (q.status = 'running' and q.lease_expires_at <= now()))
      order by
        case
          when q.type = 'discover' and not exists (
                 select 1 from public.channels ch
                  where ch.id = q.channel_id and ch.catalogued_at is not null)
            then 0
          when q.type = 'discover' and (
                 select ch.catalogued_at from public.channels ch where ch.id = q.channel_id)
               <= now() - make_interval(mins => private.catalogue_interval_or_default(q.workspace_id))
                        - interval '6 hours'
            then 1
          when q.type <> 'discover' then 2
          else 3
        end,
        case when w is null then (
          select count(*) from public.jobs r
           where r.workspace_id = q.workspace_id
             and r.status = 'running'
             and r.lease_expires_at > now()
        ) else 0 end,
        q.not_before,
        q.id
      for update skip locked limit 1)
  returning j.* into claimed;

  if claimed.id is null then return; end if;

  insert into public.sync_runs(workspace_id, channel_id, job_id, mode, source,
                               status)
  values (claimed.workspace_id, claimed.channel_id, claimed.id,
          case when claimed.type in ('discover','collect','analyse','import')
               then claimed.type else 'collect' end,
          'unknown', 'running')
  on conflict (workspace_id, job_id) do update
    set status = 'running', ended_at = null, error_code = null;

  return next claimed;
end $function$

CREATE OR REPLACE FUNCTION private.commit_batch(j uuid, t uuid, b text, hash text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  w uuid; ch uuid; vid uuid; prior text; outcome text;
  inserted int; keys text[]; covered text[]; wanted int;
  j_type text; j_payload jsonb; is_hist boolean;
  ch_platform text;
BEGIN
  SELECT workspace_id, channel_id, type, payload
  INTO w, ch, j_type, j_payload
  FROM public.jobs
  WHERE id=j AND lease_token=t AND lease_expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'lease_lost' USING errcode='P0001'; END IF;
  IF b IS NULL OR length(b) NOT BETWEEN 1 AND 200 OR hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'invalid_batch' USING errcode='22023'; END IF;
  IF jsonb_array_length(coalesce(payload->'comments','[]'::jsonb)) > 500
     OR jsonb_array_length(coalesce(payload->'predictions','[]'::jsonb)) > 500 THEN
    RAISE EXCEPTION 'batch_too_large' USING errcode='22023'; END IF;
  outcome := payload->>'outcome';
  IF outcome NOT IN ('partial','exhausted','blocked','failed') THEN
    RAISE EXCEPTION 'invalid_batch' USING errcode='22023'; END IF;

  SELECT coalesce(platform, 'youtube') INTO ch_platform FROM public.channels WHERE id=ch;

  IF (SELECT count(DISTINCT c->>'external_comment_id')
      FROM jsonb_array_elements(coalesce(payload->'comments','[]'::jsonb)) c)
     <> jsonb_array_length(coalesce(payload->'comments','[]'::jsonb)) THEN
    RAISE EXCEPTION 'invalid_batch' USING errcode='22023'; END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(coalesce(payload->'predictions','[]'::jsonb)) p
    WHERE NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(coalesce(payload->'comments','[]'::jsonb)) c
      WHERE c->>'external_comment_id' = p->>'external_comment_id')
  ) THEN RAISE EXCEPTION 'invalid_batch' USING errcode='22023'; END IF;

  SELECT payload_hash INTO prior FROM private.job_batches WHERE job_id=j AND batch_key=b;
  IF FOUND THEN
    IF prior IS DISTINCT FROM hash THEN RAISE EXCEPTION 'batch_conflict' USING errcode='23505'; END IF;
    RETURN jsonb_build_object('replayed', true);
  END IF;

  is_hist := (j_type = 'import' OR coalesce(j_payload->>'is_historical', 'false') = 'true' OR coalesce(payload->>'is_historical', 'false') = 'true');

  INSERT INTO public.videos(workspace_id,channel_id,platform,external_video_id,title,kind)
  VALUES (w, ch, ch_platform, payload->>'external_video_id',
          coalesce(nullif(payload->>'video_title',''), payload->>'external_video_id'),
          coalesce(payload->>'video_kind', payload->>'kind', CASE WHEN ch_platform = 'telegram' THEN 'channel_post' WHEN ch_platform = 'x' THEN 'tweet' ELSE 'video' END))
  ON CONFLICT (workspace_id,platform,external_video_id) DO UPDATE
    SET last_observed_at = now(),
        kind = coalesce(excluded.kind, public.videos.kind),
        title = CASE
                  WHEN excluded.title <> public.videos.external_video_id
                    THEN excluded.title
                  ELSE public.videos.title
                END
  RETURNING id INTO vid;

  INSERT INTO public.comments(
    workspace_id,video_id,platform,external_comment_id,external_parent_id,is_reply,parent_source,
    author_channel_id,author_name,text_raw,text_plain,content_hash,published_time_raw,
    published_at,timestamp_precision,likes_raw,likes_value,source,field_provenance,
    author_profile_image_url,author_channel_url,reply_count,updated_at)
  SELECT w, vid, ch_platform, c.external_comment_id, c.external_parent_id, coalesce(c.is_reply, false), coalesce(c.parent_source, 'unknown'),
         c.author_channel_id, c.author_name, c.text_raw, c.text_plain, c.content_hash,
         c.published_time_raw, c.published_at, coalesce(c.timestamp_precision, 'second'), c.likes_raw,
         c.likes_value, coalesce(c.source, 'unknown'), coalesce(c.field_provenance, '{}'::jsonb),
         c.author_profile_image_url, c.author_channel_url, coalesce(c.reply_count, 0), c.updated_at
  FROM jsonb_to_recordset(payload->'comments') AS c(
    external_comment_id text, external_parent_id text, is_reply boolean, parent_source text,
    author_channel_id text, author_name text, text_raw text, text_plain text, content_hash text,
    published_time_raw text, published_at timestamptz, timestamp_precision text,
    likes_raw text, likes_value bigint, source text, field_provenance jsonb,
    author_profile_image_url text, author_channel_url text, reply_count int, updated_at timestamptz)
  ON CONFLICT (workspace_id,platform,external_comment_id) DO UPDATE SET
    text_raw=excluded.text_raw, text_plain=excluded.text_plain,
    content_hash=excluded.content_hash, likes_raw=excluded.likes_raw,
    likes_value=excluded.likes_value, field_provenance=coalesce(excluded.field_provenance, public.comments.field_provenance),
    author_profile_image_url=coalesce(excluded.author_profile_image_url, public.comments.author_profile_image_url),
    author_channel_url=coalesce(excluded.author_channel_url, public.comments.author_channel_url),
    reply_count=coalesce(excluded.reply_count, public.comments.reply_count),
    updated_at=coalesce(excluded.updated_at, public.comments.updated_at),
    last_seen_at=now();
  GET DIAGNOSTICS inserted = row_count;

  -- Metering logic
  IF is_hist THEN
    SELECT coalesce(array_agg(DISTINCT 'backfill:'||ch_platform||':'||(c->>'external_comment_id')),'{}')
    INTO keys FROM jsonb_array_elements(coalesce(payload->'comments','[]'::jsonb)) c;
    wanted := coalesce(array_length(keys,1),0);
    IF wanted > 0 THEN
      covered := private.reserve_usage(w, 'historical_backfill', keys);
      IF coalesce(array_length(covered,1),0) <> wanted THEN
        RAISE EXCEPTION 'quota_exceeded' USING errcode='53400';
      END IF;
    END IF;
  ELSE
    IF jsonb_array_length(coalesce(payload->'predictions','[]'::jsonb)) > 0 THEN
      SELECT coalesce(array_agg(DISTINCT 'analysis:'||ch_platform||':'||(p->>'external_comment_id')),'{}')
      INTO keys FROM jsonb_array_elements(payload->'predictions') p
      WHERE p->>'status'='succeeded';
      wanted := coalesce(array_length(keys,1),0);
      IF wanted > 0 THEN
        covered := private.reserve_usage(w,'comment_analysis',keys);
        IF coalesce(array_length(covered,1),0) <> wanted THEN
          RAISE EXCEPTION 'quota_exceeded' USING errcode='53400'; END IF;
      END IF;
    END IF;
  END IF;

  IF jsonb_array_length(coalesce(payload->'predictions','[]'::jsonb)) > 0 THEN
    INSERT INTO public.analysis_runs(
      workspace_id,model_id,revision_sha,preprocessing_version,parameters,status)
    SELECT DISTINCT w, p->>'model_id', p->>'revision', p->>'preprocessing_version',
           coalesce(p->'parameters','{}'::jsonb), 'succeeded'
    FROM jsonb_array_elements(payload->'predictions') p
    ON CONFLICT (workspace_id,model_id,revision_sha,preprocessing_version,parameters) DO NOTHING;

    INSERT INTO public.sentiment_predictions(
      workspace_id,comment_id,content_hash,analysis_run_id,analysis_key,status,label,class_scores)
    SELECT w, cm.id, p.content_hash, r.id, p.analysis_key, p.status, p.label, p.class_scores
    FROM jsonb_to_recordset(payload->'predictions') AS p(
      external_comment_id text, content_hash text, analysis_key text, status text,
      label text, class_scores jsonb, model_id text, revision text,
      preprocessing_version text, parameters jsonb)
    JOIN public.comments cm ON cm.workspace_id=w AND cm.platform=ch_platform
      AND cm.external_comment_id=p.external_comment_id
    JOIN public.analysis_runs r ON r.workspace_id=w AND r.model_id=p.model_id
      AND r.revision_sha=p.revision AND r.preprocessing_version=p.preprocessing_version
      AND r.parameters=coalesce(p.parameters,'{}'::jsonb)
    ON CONFLICT (workspace_id,comment_id,content_hash,analysis_key) DO UPDATE SET
      status=excluded.status, label=excluded.label, class_scores=excluded.class_scores,
      analysis_run_id=excluded.analysis_run_id, predicted_at=now()
    WHERE public.sentiment_predictions.status = 'failed';
  END IF;

  INSERT INTO private.job_batches(job_id,batch_key,checkpoint,payload_hash,outcome)
  VALUES (j, b, coalesce(payload->'checkpoint','{}'::jsonb), hash, outcome);
  UPDATE public.jobs SET checkpoint=coalesce(payload->'checkpoint','{}'::jsonb) WHERE id=j;

  INSERT INTO public.sync_runs(workspace_id, channel_id, job_id, mode, source, status)
  VALUES (w, ch, j, case when is_hist then 'backfill' else 'collect' end,
          coalesce((SELECT c->>'source'
                      FROM jsonb_array_elements(coalesce(payload->'comments','[]'::jsonb)) c
                     LIMIT 1), 'unknown'),
          'running')
  ON CONFLICT (workspace_id, job_id) DO NOTHING;

  UPDATE public.sync_runs r SET coverage_summary = (
    WITH seen AS (
      SELECT coalesce(r.coverage_summary->'videos', '[]'::jsonb)
             || jsonb_build_array(vid::text) AS v)
    SELECT jsonb_build_object(
      'videos', (SELECT jsonb_agg(DISTINCT e)
                   FROM seen, jsonb_array_elements_text(seen.v) e),
      'videos_seen', (SELECT count(DISTINCT e)
                        FROM seen, jsonb_array_elements_text(seen.v) e),
      'comments_collected',
        coalesce((r.coverage_summary->>'comments_collected')::int, 0) + inserted,
      'complete', outcome = 'exhausted')
  )
  WHERE r.workspace_id = w AND r.job_id = j;

  RETURN jsonb_build_object('replayed', false, 'comments', inserted, 'video_id', vid);
END $function$

CREATE OR REPLACE FUNCTION private.commit_checkpoint(j uuid, t uuid, p jsonb, b text, usage_keys text[] DEFAULT '{}'::text[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare old jsonb; w uuid; covered text[]; wanted int; begin
 select workspace_id into w from public.jobs
 where id=j and lease_token=t and status='running' and lease_expires_at>now() for update;
 if not found then raise exception 'lease_lost' using errcode='P0001'; end if;
 if jsonb_typeof(p)<>'object' or b is null or length(b) not between 1 and 200 then raise exception 'invalid_batch'; end if;
 select checkpoint into old from private.job_batches where job_id=j and batch_key=b;
 if found then
 -- A replay of a committed batch is already paid for; it must not meter again.
 if old<>p then raise exception 'batch_conflict'; end if; return;
 end if;
 wanted := coalesce(array_length(usage_keys,1),0);
 if wanted > 0 then
 covered := private.reserve_usage(w,'comment_analysis',usage_keys);
 -- Rows, checkpoint and meter move together. A batch that cannot be paid for
 -- in full is refused outright rather than committed half-metered.
 if coalesce(array_length(covered,1),0) <> wanted then
 raise exception 'quota_exceeded' using errcode='53400'; end if;
 end if;
 insert into private.job_batches values(j,b,p);
 update public.jobs set checkpoint=p where id=j;
end $function$

CREATE OR REPLACE FUNCTION private.confirm_usage(w uuid, keys text[])
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n int; begin
 update public.usage_events set state='charged'
 where workspace_id=w and event_key=any(keys) and state='reserved';
 get diagnostics n = row_count; return n;
end $function$

CREATE OR REPLACE FUNCTION private.create_workspace_impl(workspace_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid; home uuid; allowed int; owned int; begin
  if auth.uid() is null then raise exception 'unauthenticated' using errcode='42501'; end if;
  home := private.owner_plan_workspace(auth.uid());
  if home is not null then
    allowed := private.plan_limit(home,'workspaces');
    select count(*) into owned from public.workspaces where created_by = auth.uid();
    if allowed is not null and owned - 1 >= allowed then
      raise exception 'workspace_limit_reached' using errcode='53400'; end if;
  end if;
  insert into public.workspaces(name,created_by) values(workspace_name,auth.uid()) returning id into w;
  insert into public.memberships values(w,auth.uid(),'workspace_owner');
  insert into public.clients(workspace_id,name) values(w,workspace_name);
  if home is not null then
    insert into public.subscriptions(workspace_id, plan_key, status, period_start, period_end, provider, provider_ref, billing_workspace_id)
    select w, s.plan_key, s.status, s.period_start, s.period_end, s.provider, s.provider_ref, home
    from public.subscriptions s where s.workspace_id = home
    on conflict (workspace_id) do nothing;
  end if;
  perform private.grant_default_plan(w);
  return w;
end $function$

CREATE OR REPLACE FUNCTION private.dashboard_aggregates_compute(w uuid, f jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  active text;
  topic_active text;
  rev text;
  taxonomy jsonb;
  res jsonb;
  active_labels text[];
  v_platform text := f->>'platform';
  v_video text := f->>'video';
  v_video_kind text := f->>'video_kind';
  v_sentiment text := f->>'sentiment';
  v_topic text := f->>'topic';
  v_replies text := f->>'replies';
  v_comment_type text := f->>'comment_type';
  v_review_status text := f->>'review_status';
  v_from timestamptz := NULLIF(f->>'from', '')::timestamptz;
  v_to timestamptz := NULLIF(f->>'to', '')::timestamptz;
  v_search text := NULLIF(trim(f->>'q'), '');
BEGIN
  IF NOT (coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role' OR private.has_role(w)) THEN
    RAISE EXCEPTION 'forbidden' USING errcode = '42501';
  END IF;

  SELECT c.active_analysis_key INTO active FROM public.channels c
   WHERE c.workspace_id = w AND c.active_analysis_key IS NOT NULL
   ORDER BY (c.status = 'connected') DESC, c.id LIMIT 1;

  SELECT active_topic_key INTO topic_active FROM public.workspaces WHERE id = w;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'key', tp.key, 'name_ar', tp.name_ar, 'name_en', tp.name_en,
      'description', tp.description, 'position', tp.position,
      'retired', tp.retired_at IS NOT NULL) ORDER BY tp.position), '[]'::jsonb)
    INTO taxonomy FROM public.workspace_topics tp WHERE tp.workspace_id = w;

  SELECT coalesce(max(s.ended_at)::text, max(s.started_at)::text, 'empty') INTO rev
   FROM public.sync_runs s WHERE s.workspace_id = w;

  -- Derive active measurable labels from the active analysis predictions
  IF active IS NOT NULL THEN
    SELECT coalesce(array_agg(DISTINCT k), ARRAY[]::text[])
      INTO active_labels
      FROM (
        SELECT jsonb_object_keys(p.class_scores) AS k
        FROM public.sentiment_predictions p
        WHERE p.workspace_id = w AND p.analysis_key = active AND p.status = 'succeeded'
        LIMIT 100
      ) sub;
  END IF;

  IF active_labels IS NULL OR cardinality(active_labels) = 0 THEN
    IF active ILIKE '%camelbert%' THEN
      active_labels := ARRAY['positive', 'negative', 'neutral'];
    ELSE
      active_labels := ARRAY['positive', 'negative', 'neutral', 'mixed'];
    END IF;
  END IF;

  WITH ch AS (
    SELECT c.id as channel_id, c.client_id, c.external_channel_id, c.active_analysis_key,
           c.title as channel_title, c.avatar_url as channel_avatar_url,
           c.subscriber_count, c.total_view_count as channel_view_count, c.video_count as channel_video_count
    FROM public.channels c
    WHERE c.workspace_id = w
    ORDER BY (c.status = 'connected') DESC, c.id LIMIT 1
  ),
  distinct_videos AS (
    SELECT
      v.id,
      v.title,
      v.kind,
      v.thumbnail_url,
      v.view_count,
      v.like_count,
      v.reported_comment_count
    FROM public.videos v
    WHERE v.workspace_id = w
      AND (v_platform IS NULL OR v.platform = v_platform)
      AND (v_video IS NULL OR v.id::text = v_video)
      AND (v_video_kind IS NULL OR v.kind = v_video_kind)
  ),
  video_kpis AS (
    SELECT
      sum(view_count) AS total_views,
      sum(like_count) AS total_likes,
      sum(reported_comment_count) AS total_reported_comments
    FROM distinct_videos
  ),
  raw_comments AS (
    SELECT
      cm.id,
      cm.video_id,
      cm.platform,
      cm.published_at,
      cm.likes_value,
      cm.is_reply,
      cm.author_name,
      cm.author_channel_id,
      cm.author_profile_image_url,
      cm.author_channel_url,
      cm.reply_count,
      cm.content_hash,
      CASE WHEN v_search IS NOT NULL THEN cm.text_raw ELSE NULL END AS text_raw,
      coalesce(cm.author_channel_id IS NOT NULL AND cm.author_channel_id = ch.external_channel_id, false) AS by_owner
    FROM public.comments cm
    LEFT JOIN ch ON true
    WHERE cm.workspace_id = w
      AND (v_platform IS NULL OR cm.platform = v_platform)
      AND (v_video IS NULL OR cm.video_id::text = v_video)
      AND (v_video_kind IS NULL OR cm.video_id IN (SELECT id FROM distinct_videos))
  ),
  rev_cte AS (
    SELECT DISTINCT ON (rv.comment_id)
      rv.comment_id, rv.content_hash, rv.label
    FROM public.comment_reviews rv
    WHERE rv.workspace_id = w AND rv.origin = 'human'
    ORDER BY rv.comment_id, rv.created_at DESC
  ),
  pred_cte AS (
    SELECT p.comment_id, p.content_hash, p.label
    FROM public.sentiment_predictions p
    WHERE p.workspace_id = w AND active IS NOT NULL AND p.analysis_key = active AND p.status = 'succeeded'
  ),
  tr_rev AS (
    SELECT DISTINCT ON (tr.comment_id)
      tr.comment_id, tr.content_hash, tr.topic_key
    FROM public.topic_reviews tr
    WHERE tr.workspace_id = w AND tr.origin = 'human'
    ORDER BY tr.comment_id, tr.created_at DESC
  ),
  tp_cte AS (
    SELECT tp.comment_id, tp.content_hash, tp.topic_key
    FROM public.topic_predictions tp
    WHERE tp.workspace_id = w AND topic_active IS NOT NULL AND tp.classification_key = topic_active AND tp.status = 'succeeded'
  ),
  ann_cte AS (
    SELECT DISTINCT ON (a.comment_id) a.comment_id, a.value
    FROM public.comment_annotations a
    WHERE a.workspace_id = w AND a.kind = 'comment_type'
    ORDER BY a.comment_id, a.created_at DESC
  ),
  evaluated AS (
    SELECT
      rc.*,
      ann.value AS comment_type,
      (rev.comment_id IS NOT NULL AND rev.content_hash = rc.content_hash) AS reviewed,
      CASE
        WHEN rev.content_hash = rc.content_hash THEN rev.label
        WHEN pred.content_hash = rc.content_hash THEN pred.label
        ELSE NULL
      END AS eff_label,
      CASE
        WHEN tr.content_hash = rc.content_hash THEN tr.topic_key
        WHEN tp.content_hash = rc.content_hash THEN tp.topic_key
        ELSE NULL
      END AS eff_topic
    FROM raw_comments rc
    LEFT JOIN rev_cte rev ON rev.comment_id = rc.id
    LEFT JOIN pred_cte pred ON pred.comment_id = rc.id
    LEFT JOIN tr_rev tr ON tr.comment_id = rc.id
    LEFT JOIN tp_cte tp ON tp.comment_id = rc.id
    LEFT JOIN ann_cte ann ON ann.comment_id = rc.id
  ),
  filtered AS (
    SELECT * FROM evaluated e
    WHERE (v_sentiment IS NULL OR e.eff_label = v_sentiment)
      AND (v_topic IS NULL OR (v_topic = '__unclassified' AND e.eff_topic IS NULL) OR (e.eff_topic = v_topic))
      AND (v_replies IS NULL OR v_replies = 'all' OR (v_replies = 'comments' AND NOT e.is_reply) OR (v_replies = 'replies' AND e.is_reply))
      AND (v_comment_type IS NULL OR e.comment_type = v_comment_type)
      AND (v_review_status IS NULL OR v_review_status = 'all' OR (v_review_status = 'reviewed' AND e.reviewed) OR (v_review_status = 'unreviewed' AND NOT e.reviewed))
      AND (v_from IS NULL OR e.published_at >= v_from)
      AND (v_to IS NULL OR e.published_at < v_to)
      AND (v_search IS NULL OR e.text_raw ILIKE '%' || v_search || '%' OR e.author_name ILIKE '%' || v_search || '%')
  ),
  summary_stats AS (
    SELECT
      count(*) AS workspace_total,
      count(*) FILTER (WHERE by_owner) AS channel_own_comments,
      count(*) FILTER (WHERE NOT by_owner) AS total,
      count(*) FILTER (WHERE NOT by_owner AND eff_label IS NOT NULL) AS analysed,
      count(*) FILTER (WHERE NOT by_owner AND eff_label = 'positive') AS positive,
      count(*) FILTER (WHERE NOT by_owner AND eff_label = 'negative') AS negative,
      count(*) FILTER (WHERE NOT by_owner AND eff_label = 'neutral') AS neutral,
      count(*) FILTER (WHERE NOT by_owner AND eff_label = 'mixed') AS mixed,
      count(*) FILTER (WHERE NOT by_owner AND eff_label = 'negative' AND likes_value IS NOT NULL) AS negative_ranked,
      count(*) FILTER (WHERE NOT by_owner AND eff_label = 'negative' AND likes_value IS NULL) AS negative_unranked,
      count(*) FILTER (WHERE NOT by_owner AND is_reply) AS replies,
      count(*) FILTER (WHERE NOT by_owner AND published_at IS NULL) AS unknown_dates,
      count(DISTINCT NULLIF(author_channel_id, '')) FILTER (WHERE NOT by_owner) AS unique_authors
    FROM filtered
  ),
  platforms_agg AS (
    SELECT
      platform,
      count(*) AS cnt
    FROM filtered
    WHERE NOT by_owner
    GROUP BY platform
  ),
  timeline_agg AS (
    SELECT
      to_char(published_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') AS day,
      count(*) AS cnt
    FROM filtered
    WHERE NOT by_owner AND published_at IS NOT NULL
    GROUP BY 1
  ),
  topics_agg AS (
    SELECT
      coalesce(eff_topic, '__unclassified') AS topic_key,
      count(*) AS cnt
    FROM filtered
    WHERE NOT by_owner
    GROUP BY 1
  ),
  videos_sub AS (
    SELECT
      f.video_id,
      count(*) AS total,
      count(*) FILTER (WHERE eff_label IS NOT NULL) AS analysed,
      count(*) FILTER (WHERE is_reply) AS replies,
      jsonb_build_object(
        'positive', count(*) FILTER (WHERE eff_label = 'positive'),
        'negative', count(*) FILTER (WHERE eff_label = 'negative'),
        'neutral', count(*) FILTER (WHERE eff_label = 'neutral'),
        'mixed', count(*) FILTER (WHERE eff_label = 'mixed')
      ) AS sentiments
    FROM filtered f
    WHERE NOT by_owner
    GROUP BY f.video_id
  ),
  videos_agg AS (
    SELECT
      vs.video_id::text AS id,
      dv.title,
      dv.thumbnail_url,
      dv.view_count,
      dv.like_count,
      dv.reported_comment_count,
      vs.total,
      vs.analysed,
      vs.replies,
      vs.sentiments
    FROM videos_sub vs
    JOIN distinct_videos dv ON dv.id = vs.video_id
  ),
  hours_counts AS (
    SELECT
      extract(hour FROM published_at AT TIME ZONE 'UTC')::int AS h,
      count(*) AS cnt
    FROM filtered
    WHERE NOT by_owner AND published_at IS NOT NULL
    GROUP BY 1
  ),
  hours_agg AS (
    SELECT jsonb_agg(coalesce(hc.cnt, 0) ORDER BY gs.h) AS hours
    FROM generate_series(0, 23) gs(h)
    LEFT JOIN hours_counts hc ON hc.h = gs.h
  ),
  weekdays_counts AS (
    SELECT
      extract(dow FROM published_at AT TIME ZONE 'UTC')::int AS d,
      count(*) AS cnt
    FROM filtered
    WHERE NOT by_owner AND published_at IS NOT NULL
    GROUP BY 1
  ),
  weekdays_agg AS (
    SELECT jsonb_agg(coalesce(wc.cnt, 0) ORDER BY gs.d) AS weekdays
    FROM generate_series(0, 6) gs(d)
    LEFT JOIN weekdays_counts wc ON wc.d = gs.d
  ),
  weeks_agg AS (
    SELECT coalesce(jsonb_agg(jsonb_build_object('week', to_char(w.week_date, 'IYYY-"W"IW'), 'count', w.cnt) ORDER BY w.week_date), '[]'::jsonb) AS weeks
    FROM (
      SELECT date_trunc('week', published_at AT TIME ZONE 'UTC') AS week_date, count(*) AS cnt
      FROM filtered
      WHERE NOT by_owner AND published_at IS NOT NULL
      GROUP BY 1
    ) w
  ),
  people_agg AS (
    SELECT coalesce(jsonb_agg(p.*), '[]'::jsonb) AS people
    FROM (
      SELECT
        coalesce(author_name, 'unknown') AS name,
        author_channel_id AS channel_id,
        (array_agg(author_profile_image_url) FILTER (WHERE author_profile_image_url IS NOT NULL))[1] AS avatar_url,
        (array_agg(author_channel_url) FILTER (WHERE author_channel_url IS NOT NULL))[1] AS channel_url,
        count(*) AS comments_count,
        coalesce(sum(likes_value), 0) AS likes_count
      FROM filtered
      WHERE NOT by_owner
      GROUP BY 1, 2
      ORDER BY count(*) DESC
      LIMIT 10
    ) p
  ),
  engaged_negatives AS (
    SELECT coalesce(jsonb_agg(r.item), '[]'::jsonb) AS items
    FROM (
      SELECT jsonb_build_object(
        'id', f.id::text,
        'video_id', f.video_id::text,
        'video_title', dv.title,
        'text_raw', coalesce(cm_neg.text_raw, ''),
        'author_name', f.author_name,
        'author_profile_image_url', cm_neg.author_profile_image_url,
        'published_at', f.published_at,
        'likes_value', f.likes_value,
        'label', f.eff_label,
        'topic', f.eff_topic
      ) AS item
      FROM (
        SELECT id, video_id, author_name, published_at, likes_value, eff_label, eff_topic
        FROM filtered
        WHERE NOT by_owner AND eff_label = 'negative'
        ORDER BY likes_value DESC NULLS LAST, published_at DESC
        LIMIT 5
      ) f
      LEFT JOIN distinct_videos dv ON dv.id = f.video_id
      LEFT JOIN public.comments cm_neg ON cm_neg.id = f.id
    ) r
  ),
  distinct_types AS (
    SELECT coalesce(jsonb_agg(DISTINCT value) FILTER (WHERE value IS NOT NULL), '[]'::jsonb) AS types
    FROM public.comment_annotations
    WHERE workspace_id = w AND kind = 'comment_type'
  ),
  all_videos AS (
    SELECT coalesce(jsonb_agg(jsonb_build_object('id', v.id::text, 'title', v.title) ORDER BY v.title), '[]'::jsonb) AS opts
    FROM public.videos v
    WHERE v.workspace_id = w
  )
  SELECT jsonb_build_object(
    'workspace_total', (SELECT workspace_total FROM summary_stats),
    'channel_own_comments', (SELECT channel_own_comments FROM summary_stats),
    'total', (SELECT total FROM summary_stats),
    'analysed', (SELECT analysed FROM summary_stats),
    'unanalysed', (SELECT total - analysed FROM summary_stats),
    'replies', (SELECT replies FROM summary_stats),
    'unknown_dates', (SELECT unknown_dates FROM summary_stats),
    'unique_authors', (SELECT unique_authors FROM summary_stats),
    'sentiments', jsonb_build_object(
      'positive', (SELECT positive FROM summary_stats),
      'negative', (SELECT negative FROM summary_stats),
      'neutral', (SELECT neutral FROM summary_stats),
      'mixed', (SELECT mixed FROM summary_stats)
    ),
    'kpis', jsonb_build_object(
      'total_views', (SELECT total_views FROM video_kpis),
      'total_likes', (SELECT total_likes FROM video_kpis),
      'total_comments', (SELECT total FROM summary_stats),
      'engagement_rate', (
        SELECT CASE
          WHEN total_views IS NOT NULL AND total_views > 0 THEN
            round(
              ((coalesce(total_likes, 0) + (SELECT total FROM summary_stats))::numeric / total_views::numeric) * 100,
              2
            )
          ELSE NULL
        END
        FROM video_kpis
      ),
      'net_sentiment', (
        SELECT round(
          ((positive - negative)::numeric / NULLIF(positive + negative, 0)::numeric) * 100,
          1
        )
        FROM summary_stats
      )
    ),
    'channel', (
      SELECT jsonb_build_object(
        'id', ch.channel_id,
        'title', ch.channel_title,
        'avatar_url', ch.channel_avatar_url,
        'subscriber_count', ch.subscriber_count,
        'view_count', ch.channel_view_count,
        'video_count', ch.channel_video_count
      ) FROM ch
    ),
    'measurable', active_labels,
    'negative_ranked', (SELECT negative_ranked FROM summary_stats),
    'negative_unranked', (SELECT negative_unranked FROM summary_stats),
    'timeline', coalesce((SELECT jsonb_object_agg(day, cnt) FROM timeline_agg), '{}'::jsonb),
    'topic_counts', coalesce((SELECT jsonb_object_agg(topic_key, cnt) FROM topics_agg), '{}'::jsonb),
    'platform_breakdown', coalesce((SELECT jsonb_object_agg(platform, cnt) FROM platforms_agg), '{}'::jsonb),
    'videos', coalesce((SELECT jsonb_agg(v.* ORDER BY v.total DESC) FROM videos_agg v), '[]'::jsonb),
    'hours', (SELECT hours FROM hours_agg),
    'weekdays', (SELECT weekdays FROM weekdays_agg),
    'weeks', (SELECT weeks FROM weeks_agg),
    'people', (SELECT people FROM people_agg),
    'most_engaged_negative', (SELECT items FROM engaged_negatives),
    'comment_types', (SELECT types FROM distinct_types),
    'video_options', (SELECT opts FROM all_videos),
    'topics', taxonomy,
    'active_analysis_key', active,
    'active_topic_key', topic_active,
    'revision', rev
  ) INTO res;

  RETURN res;
END;
$function$

CREATE OR REPLACE FUNCTION private.dashboard_aggregates_fresh_for()
 RETURNS interval
 LANGUAGE sql
 IMMUTABLE
AS $function$ select interval '60 seconds' $function$

CREATE OR REPLACE FUNCTION private.dashboard_aggregates_impl(w uuid, f jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  filters jsonb := jsonb_strip_nulls(coalesce(f, '{}'::jsonb));
  k       text;
  c       private.dashboard_aggregates_cache;
  stale   boolean;
begin
  if not (coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
          or private.has_role(w)) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  -- Free-text search is open-ended (a row per typed string would never be read
  -- twice) and is served by the trigram index, so it is still answered live.
  if nullif(trim(filters->>'q'), '') is not null then
    return private.dashboard_aggregates_compute(w, filters);
  end if;

  k := md5(filters::text);

  select * into c from private.dashboard_aggregates_cache
   where workspace_id = w and filter_key = k;

  if not found then
    insert into private.dashboard_aggregates_cache(workspace_id, filter_key, filters)
    values (w, k, filters)
    on conflict do nothing;
    return jsonb_build_object('cache', jsonb_build_object('state', 'pending'));
  end if;

  if c.payload is null then
    update private.dashboard_aggregates_cache
       set requested_at = now()
     where workspace_id = w and filter_key = k;
    if c.last_error is not null then
      return jsonb_build_object('cache',
        jsonb_build_object('state', 'failed', 'error', c.last_error));
    end if;
    return jsonb_build_object('cache', jsonb_build_object('state', 'pending'));
  end if;

  stale := c.computed_at < now() - private.dashboard_aggregates_fresh_for();
  if stale or c.requested_at < now() - interval '1 hour' then
    -- Queue a refresh (and keep the row alive); once per staleness, not per read.
    if c.requested_at <= c.computed_at or c.requested_at < now() - interval '1 hour' then
      update private.dashboard_aggregates_cache
         set requested_at = now()
       where workspace_id = w and filter_key = k;
    end if;
  end if;

  return c.payload || jsonb_build_object('cache', jsonb_build_object(
    'state', case when stale then 'stale' else 'fresh' end,
    'computed_at', c.computed_at));
end
$function$

CREATE OR REPLACE FUNCTION private.dashboard_comments_impl(w uuid, f jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  active text;
  topic_active text;
  p_limit int := LEAST(COALESCE((f->>'limit')::int, 25), 100);
  p_offset int := GREATEST(COALESCE((f->>'offset')::int, 0), 0);
  p_sort text := COALESCE(f->>'sort', 'published_desc');
  p_after text := NULLIF(f->>'after', '');
  p_with_total boolean := COALESCE((f->>'with_total')::boolean, true);
  p_card_tab text := f->>'card_tab';
  v_platform text := f->>'platform';
  v_video text := f->>'video';
  v_video_kind text := f->>'video_kind';
  v_sentiment text := f->>'sentiment';
  v_topic text := f->>'topic';
  v_replies text := f->>'replies';
  v_comment_type text := f->>'comment_type';
  v_review_status text := f->>'review_status';
  v_from timestamptz := NULLIF(f->>'from', '')::timestamptz;
  v_to timestamptz := NULLIF(f->>'to', '')::timestamptz;
  v_search text := NULLIF(trim(f->>'q'), '');
  cursor_payload jsonb;
  cursor_id uuid;
  cursor_published timestamptz;
  cursor_likes bigint;
  total_matches int := NULL;
  comments_list jsonb := '[]'::jsonb;
  next_cur text := NULL;
  has_more_flag boolean := false;
BEGIN
  IF NOT (coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role' OR private.has_role(w)) THEN
    RAISE EXCEPTION 'forbidden' USING errcode = '42501';
  END IF;

  SELECT c.active_analysis_key INTO active FROM public.channels c
   WHERE c.workspace_id = w AND c.active_analysis_key IS NOT NULL
   ORDER BY (c.status = 'connected') DESC, c.id LIMIT 1;

  SELECT active_topic_key INTO topic_active FROM public.workspaces WHERE id = w;

  IF p_card_tab = 'critical' THEN
    v_sentiment := 'negative';
    p_sort := 'likes_desc';
  ELSIF p_card_tab = 'recent' THEN
    p_sort := 'published_desc';
  ELSIF p_card_tab = 'liked' THEN
    p_sort := 'likes_desc';
  END IF;

  IF p_after IS NOT NULL THEN
    BEGIN
      cursor_payload := convert_from(decode(p_after, 'hex'), 'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid_cursor' USING errcode = '22023';
    END;
    IF jsonb_typeof(cursor_payload) <> 'object'
       OR cursor_payload->>'sort' IS DISTINCT FROM p_sort
       OR NOT (cursor_payload ? 'id')
       OR NOT (cursor_payload ? 'published_at')
       OR (p_sort IN ('likes_desc', 'likes_asc') AND NOT (cursor_payload ? 'likes_value')) THEN
      RAISE EXCEPTION 'invalid_cursor' USING errcode = '22023';
    END IF;
    BEGIN
      cursor_id := (cursor_payload->>'id')::uuid;
      cursor_published := NULLIF(cursor_payload->>'published_at', '')::timestamptz;
      cursor_likes := NULLIF(cursor_payload->>'likes_value', '')::bigint;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid_cursor' USING errcode = '22023';
    END;
    -- Check ownership without revealing whether the id exists elsewhere.
    IF NOT EXISTS (
      SELECT 1 FROM public.comments cm
      WHERE cm.id = cursor_id AND cm.workspace_id = w
    ) THEN
      RAISE EXCEPTION 'invalid_cursor' USING errcode = '22023';
    END IF;
  END IF;

  WITH ch AS (
    SELECT c.id as channel_id, c.client_id, c.external_channel_id, c.active_analysis_key
    FROM public.channels c
    WHERE c.workspace_id = w
    ORDER BY (c.status = 'connected') DESC, c.id LIMIT 1
  ),
  distinct_videos AS (
    SELECT v.id, v.title, v.kind, v.channel_id
    FROM public.videos v
    WHERE v.workspace_id = w
      AND (v_video IS NULL OR v.id::text = v_video)
      AND (v_video_kind IS NULL OR v.kind = v_video_kind)
  ),
  raw_keys AS (
    SELECT
      cm.id,
      cm.video_id,
      cm.platform,
      cm.published_at,
      cm.likes_value,
      cm.is_reply,
      cm.content_hash,
      coalesce(cm.author_channel_id IS NOT NULL AND cm.author_channel_id = ch.external_channel_id, false) AS by_owner
    FROM public.comments cm
    LEFT JOIN ch ON true
    WHERE cm.workspace_id = w
      AND (v_platform IS NULL OR cm.platform = v_platform)
      AND (v_video IS NULL OR cm.video_id::text = v_video)
      AND (v_video_kind IS NULL OR cm.video_id IN (SELECT id FROM distinct_videos))
      AND (v_from IS NULL OR cm.published_at >= v_from)
      AND (v_to IS NULL OR cm.published_at < v_to)
      AND (v_replies IS NULL OR v_replies = 'all' OR (v_replies = 'comments' AND NOT cm.is_reply) OR (v_replies = 'replies' AND cm.is_reply))
  ),
  rev_cte AS (
    SELECT DISTINCT ON (rv.comment_id)
      rv.comment_id, rv.content_hash, rv.label
    FROM public.comment_reviews rv
    WHERE rv.workspace_id = w AND rv.origin = 'human'
    ORDER BY rv.comment_id, rv.created_at DESC
  ),
  pred_cte AS (
    SELECT p.comment_id, p.content_hash, p.label
    FROM public.sentiment_predictions p
    WHERE p.workspace_id = w AND active IS NOT NULL AND p.analysis_key = active AND p.status = 'succeeded'
  ),
  tr_rev AS (
    SELECT DISTINCT ON (tr.comment_id)
      tr.comment_id, tr.content_hash, tr.topic_key
    FROM public.topic_reviews tr
    WHERE tr.workspace_id = w AND tr.origin = 'human'
    ORDER BY tr.comment_id, tr.created_at DESC
  ),
  tp_cte AS (
    SELECT tp.comment_id, tp.content_hash, tp.topic_key
    FROM public.topic_predictions tp
    WHERE tp.workspace_id = w AND topic_active IS NOT NULL AND tp.classification_key = topic_active AND tp.status = 'succeeded'
  ),
  ann_cte AS (
    SELECT DISTINCT ON (a.comment_id) a.comment_id, a.value
    FROM public.comment_annotations a
    WHERE a.workspace_id = w AND a.kind = 'comment_type'
    ORDER BY a.comment_id, a.created_at DESC
  ),
  evaluated AS (
    SELECT
      rk.*,
      ann.value AS comment_type,
      (rev.comment_id IS NOT NULL AND rev.content_hash = rk.content_hash) AS reviewed,
      CASE
        WHEN rev.content_hash = rk.content_hash THEN rev.label
        WHEN pred.content_hash = rk.content_hash THEN pred.label
        ELSE NULL
      END AS eff_label,
      CASE
        WHEN tr.content_hash = rk.content_hash THEN tr.topic_key
        WHEN tp.content_hash = rk.content_hash THEN tp.topic_key
        ELSE NULL
      END AS eff_topic
    FROM raw_keys rk
    LEFT JOIN rev_cte rev ON rev.comment_id = rk.id
    LEFT JOIN pred_cte pred ON pred.comment_id = rk.id
    LEFT JOIN tr_rev tr ON tr.comment_id = rk.id
    LEFT JOIN tp_cte tp ON tp.comment_id = rk.id
    LEFT JOIN ann_cte ann ON ann.comment_id = rk.id
  ),
  filtered AS (
    SELECT e.* FROM evaluated e
    WHERE (v_sentiment IS NULL OR e.eff_label = v_sentiment)
      AND (v_topic IS NULL OR (v_topic = '__unclassified' AND e.eff_topic IS NULL) OR (e.eff_topic = v_topic))
      AND (v_comment_type IS NULL OR e.comment_type = v_comment_type)
      AND (v_review_status IS NULL OR v_review_status = 'all' OR (v_review_status = 'reviewed' AND e.reviewed) OR (v_review_status = 'unreviewed' AND NOT e.reviewed))
      AND (
        v_search IS NULL OR
        EXISTS (
          SELECT 1 FROM public.comments scm
          WHERE scm.id = e.id AND (scm.text_raw ILIKE '%' || v_search || '%' OR scm.author_name ILIKE '%' || v_search || '%')
        )
      )
  ),
  counted AS (
    SELECT count(*)::int AS cnt FROM filtered
    HAVING p_with_total
  ),
  sorted_page AS (
    SELECT f.* FROM filtered f
    WHERE p_after IS NULL OR
      CASE p_sort
        WHEN 'published_desc' THEN
          (cursor_published IS NOT NULL AND (f.published_at < cursor_published OR f.published_at IS NULL))
          OR (f.published_at IS NOT DISTINCT FROM cursor_published AND f.id < cursor_id)
        WHEN 'published_asc' THEN
          (cursor_published IS NOT NULL AND (f.published_at > cursor_published OR f.published_at IS NULL))
          OR (f.published_at IS NOT DISTINCT FROM cursor_published AND f.id < cursor_id)
        WHEN 'likes_desc' THEN
          (cursor_likes IS NOT NULL AND (f.likes_value < cursor_likes OR f.likes_value IS NULL))
          OR (f.likes_value IS NOT DISTINCT FROM cursor_likes AND (
            (cursor_published IS NOT NULL AND (f.published_at < cursor_published OR f.published_at IS NULL))
            OR (f.published_at IS NOT DISTINCT FROM cursor_published AND f.id < cursor_id)
          ))
        WHEN 'likes_asc' THEN
          (cursor_likes IS NOT NULL AND (f.likes_value > cursor_likes OR f.likes_value IS NULL))
          OR (f.likes_value IS NOT DISTINCT FROM cursor_likes AND (
            (cursor_published IS NOT NULL AND (f.published_at < cursor_published OR f.published_at IS NULL))
            OR (f.published_at IS NOT DISTINCT FROM cursor_published AND f.id < cursor_id)
          ))
        ELSE false
      END
    ORDER BY
      CASE WHEN p_sort = 'likes_desc' THEN f.likes_value END DESC NULLS LAST,
      CASE WHEN p_sort = 'likes_asc' THEN f.likes_value END ASC NULLS LAST,
      CASE WHEN p_sort = 'published_asc' THEN f.published_at END ASC NULLS LAST,
      f.published_at DESC NULLS LAST,
      f.id DESC
    LIMIT p_limit + 1 OFFSET CASE WHEN p_after IS NULL THEN p_offset ELSE 0 END
  ),
  page_with_extra AS (
    SELECT sp.*, row_number() OVER () AS rnum FROM sorted_page sp
  ),
  page_exact AS (
    SELECT * FROM page_with_extra WHERE rnum <= p_limit
  ),
  page_preds AS (
    SELECT DISTINCT ON (p.comment_id, p.content_hash)
           p.comment_id, p.content_hash,
           jsonb_build_object(
             'status', p.status, 'label', p.label, 'content_hash', p.content_hash,
             'analysis_key', p.analysis_key, 'model_id', r.model_id,
             'revision', r.revision_sha, 'preprocessing_version', r.preprocessing_version,
             'predicted_at', p.predicted_at, 'class_scores', p.class_scores
           ) AS pred_json
    FROM public.sentiment_predictions p
    JOIN page_exact pe ON pe.id = p.comment_id AND pe.content_hash = p.content_hash
    JOIN public.analysis_runs r ON r.workspace_id = w AND r.id = p.analysis_run_id
    WHERE p.workspace_id = w
      AND active IS NOT NULL AND p.analysis_key = active
    ORDER BY p.comment_id, p.content_hash, p.predicted_at DESC
  ),
  page_topic_preds AS (
    SELECT DISTINCT ON (p.comment_id, p.content_hash)
           p.comment_id, p.content_hash,
           jsonb_build_object(
             'status', p.status, 'topic_key', p.topic_key, 'confidence', p.confidence,
             'content_hash', p.content_hash, 'classification_key', p.classification_key,
             'model_id', p.model_id, 'prompt_version', p.prompt_version,
             'predicted_at', p.predicted_at, 'error_code', p.error_code
           ) AS topic_pred_json
    FROM public.topic_predictions p
    JOIN page_exact pe ON pe.id = p.comment_id AND pe.content_hash = p.content_hash
    WHERE p.workspace_id = w
      AND topic_active IS NOT NULL AND p.classification_key = topic_active
    ORDER BY p.comment_id, p.content_hash, p.predicted_at DESC
  ),
  page_reviews AS (
    SELECT rv.comment_id,
           coalesce(jsonb_agg(jsonb_build_object(
             'label', rv.label, 'content_hash', rv.content_hash,
             'created_at', rv.created_at, 'origin', rv.origin,
             'reviewer_id', rv.reviewer_id::text, 'reason', rv.reason
           ) ORDER BY rv.created_at), '[]'::jsonb) AS reviews_json
    FROM public.comment_reviews rv
    JOIN page_exact pe ON pe.id = rv.comment_id
    WHERE rv.workspace_id = w
    GROUP BY rv.comment_id
  ),
  page_topic_reviews AS (
    SELECT tr.comment_id,
           coalesce(jsonb_agg(jsonb_build_object(
             'topic_key', tr.topic_key, 'content_hash', tr.content_hash,
             'created_at', tr.created_at, 'origin', tr.origin,
             'reviewer_id', tr.reviewer_id::text, 'reason', tr.reason
           ) ORDER BY tr.created_at), '[]'::jsonb) AS topic_reviews_json
    FROM public.topic_reviews tr
    JOIN page_exact pe ON pe.id = tr.comment_id
    WHERE tr.workspace_id = w
    GROUP BY tr.comment_id
  ),
  assembled AS (
    SELECT jsonb_agg(jsonb_build_object(
      'id', pe.id::text,
      'workspace_id', cm.workspace_id::text,
      'client_id', coalesce(ch.client_id, cm.workspace_id)::text,
      'channel_id', coalesce(ch.channel_id, dv.channel_id)::text,
      'video_id', pe.video_id::text,
      'platform', pe.platform,
      'by_channel_owner', pe.by_owner,
      'video_title', dv.title,
      'video_kind', dv.kind,
      'author_channel_id', cm.author_channel_id,
      'author_name', cm.author_name,
      'author_profile_image_url', cm.author_profile_image_url,
      'author_channel_url', cm.author_channel_url,
      'reply_count', coalesce(cm.reply_count, 0),
      'updated_at', cm.updated_at,
      'text_raw', cm.text_raw,
      'content_hash', cm.content_hash,
      'likes_raw', cm.likes_raw,
      'likes_value', cm.likes_value,
      'published_at', cm.published_at,
      'published_time_raw', cm.published_time_raw,
      'timestamp_precision', cm.timestamp_precision,
      'is_reply', cm.is_reply,
      'parent_comment_id', cm.external_parent_id,
      'parent_source', cm.parent_source,
      'source', cm.source,
      'field_provenance', cm.field_provenance,
      'comment_type', pe.comment_type,
      'content_purged_at', cm.content_purged_at,
      'prediction', ap.pred_json,
      'reviews', coalesce(ra.reviews_json, '[]'::jsonb),
      'topic_prediction', atp.topic_pred_json,
      'topic_reviews', coalesce(tra.topic_reviews_json, '[]'::jsonb)
    ) ORDER BY pe.rnum) AS items
    FROM page_exact pe
    JOIN public.comments cm ON cm.id = pe.id
    LEFT JOIN distinct_videos dv ON dv.id = pe.video_id
    LEFT JOIN ch ON true
    LEFT JOIN page_preds ap ON ap.comment_id = pe.id
    LEFT JOIN page_topic_preds atp ON atp.comment_id = pe.id
    LEFT JOIN page_reviews ra ON ra.comment_id = pe.id
    LEFT JOIN page_topic_reviews tra ON tra.comment_id = pe.id
  )
  SELECT
    (SELECT cnt FROM counted),
    coalesce((SELECT items FROM assembled), '[]'::jsonb),
    (SELECT count(*) > p_limit FROM page_with_extra),
    (SELECT encode(convert_to(jsonb_build_object(
      'sort', p_sort,
      'published_at', published_at,
      'likes_value', likes_value,
      'id', id
    )::text, 'UTF8'), 'hex') FROM page_exact ORDER BY rnum DESC LIMIT 1)
  INTO total_matches, comments_list, has_more_flag, next_cur;

  RETURN jsonb_build_object(
    'total', total_matches,
    'comments', comments_list,
    'limit', p_limit,
    'offset', p_offset,
    'has_more', has_more_flag,
    'next_cursor', CASE WHEN has_more_flag THEN next_cur ELSE NULL END
  );
END;
$function$

CREATE OR REPLACE FUNCTION private.dashboard_snapshot_impl(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  active text;
  topic_active text;
  rows jsonb;
  state jsonb;
  rev text;
  taxonomy jsonb;
BEGIN
  IF NOT private.has_role(w) THEN
    RAISE EXCEPTION 'forbidden' USING errcode = '42501';
  END IF;

  -- Active analysis key
  SELECT c.active_analysis_key INTO active FROM public.channels c
   WHERE c.workspace_id = w AND c.active_analysis_key IS NOT NULL
   ORDER BY (c.status = 'connected') DESC, c.id LIMIT 1;

  SELECT active_topic_key INTO topic_active FROM public.workspaces WHERE id = w;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'key', tp.key, 'name_ar', tp.name_ar, 'name_en', tp.name_en,
      'description', tp.description, 'position', tp.position,
      'retired', tp.retired_at IS NOT NULL) ORDER BY tp.position), '[]'::jsonb)
    INTO taxonomy FROM public.workspace_topics tp WHERE tp.workspace_id = w;

  -- Revision based on recent sync runs or comments
  SELECT coalesce(max(s.ended_at)::text, max(s.started_at)::text, 'empty') INTO rev
   FROM public.sync_runs s WHERE s.workspace_id = w;

  -- Comments and their associated relations, scoped to the most recent window (1500 comments)
  -- to prevent 50+ MB memory explosions and PostgREST timeout/gateway crash while maintaining
  -- rich, interactive dashboard browsing and instant rendering.
  WITH recent_comments AS (
    SELECT cm.*, v.title AS video_title, v.kind AS video_kind,
           (cm.author_channel_id IS NOT NULL AND cm.author_channel_id = ch.external_channel_id) AS by_channel_owner
    FROM public.comments cm
    JOIN public.videos v ON v.workspace_id = w AND v.id = cm.video_id
    JOIN public.channels ch ON ch.workspace_id = w AND ch.id = v.channel_id
    WHERE cm.workspace_id = w
    ORDER BY cm.published_at DESC NULLS LAST, cm.id DESC
    LIMIT 1500
  ),
  active_pred AS (
    SELECT DISTINCT ON (p.comment_id, p.content_hash)
           p.comment_id, p.content_hash,
           json_build_object(
             'status', p.status, 'label', p.label, 'content_hash', p.content_hash,
             'analysis_key', p.analysis_key, 'model_id', r.model_id,
             'revision', r.revision_sha, 'preprocessing_version', r.preprocessing_version,
             'predicted_at', p.predicted_at, 'class_scores', p.class_scores
           ) AS pred_json
    FROM public.sentiment_predictions p
    JOIN recent_comments rc ON rc.id = p.comment_id AND rc.content_hash = p.content_hash
    JOIN public.analysis_runs r ON r.workspace_id = w AND r.id = p.analysis_run_id
    WHERE p.workspace_id = w
      AND active IS NOT NULL AND p.analysis_key = active
    ORDER BY p.comment_id, p.content_hash, p.predicted_at DESC
  ),
  active_tp AS (
    SELECT DISTINCT ON (p.comment_id, p.content_hash)
           p.comment_id, p.content_hash,
           json_build_object(
             'status', p.status, 'topic_key', p.topic_key, 'confidence', p.confidence,
             'content_hash', p.content_hash, 'classification_key', p.classification_key,
             'model_id', p.model_id, 'prompt_version', p.prompt_version,
             'predicted_at', p.predicted_at, 'error_code', p.error_code
           ) AS topic_pred_json
    FROM public.topic_predictions p
    JOIN recent_comments rc ON rc.id = p.comment_id AND rc.content_hash = p.content_hash
    WHERE p.workspace_id = w
      AND topic_active IS NOT NULL AND p.classification_key = topic_active
    ORDER BY p.comment_id, p.content_hash, p.predicted_at DESC
  ),
  reviews_agg AS (
    SELECT rv.comment_id,
           coalesce(json_agg(json_build_object(
             'label', rv.label, 'content_hash', rv.content_hash,
             'created_at', rv.created_at, 'origin', rv.origin,
             'reviewer_id', rv.reviewer_id::text, 'reason', rv.reason
           ) ORDER BY rv.created_at), '[]'::json) AS reviews_json
    FROM public.comment_reviews rv
    JOIN recent_comments rc ON rc.id = rv.comment_id
    WHERE rv.workspace_id = w
    GROUP BY rv.comment_id
  ),
  topic_reviews_agg AS (
    SELECT tr.comment_id,
           coalesce(json_agg(json_build_object(
             'topic_key', tr.topic_key, 'content_hash', tr.content_hash,
             'created_at', tr.created_at, 'origin', tr.origin,
             'reviewer_id', tr.reviewer_id::text, 'reason', tr.reason
           ) ORDER BY tr.created_at), '[]'::json) AS topic_reviews_json
    FROM public.topic_reviews tr
    JOIN recent_comments rc ON rc.id = tr.comment_id
    WHERE tr.workspace_id = w
    GROUP BY tr.comment_id
  ),
  annotations_latest AS (
    SELECT DISTINCT ON (a.comment_id) a.comment_id, a.value
    FROM public.comment_annotations a
    JOIN recent_comments rc ON rc.id = a.comment_id
    WHERE a.workspace_id = w AND a.kind = 'comment_type'
    ORDER BY a.comment_id, a.created_at DESC
  )
  SELECT coalesce(json_agg(r.row ORDER BY r.published_at NULLS LAST, r.id), '[]'::json)::jsonb
  INTO rows FROM (
    SELECT cm.id, cm.published_at, json_build_object(
      'id', cm.id::text,
      'workspace_id', cm.workspace_id::text,
      'client_id', ch.client_id::text,
      'channel_id', ch.id::text,
      'video_id', v.id::text,
      'by_channel_owner', cm.by_channel_owner,
      'video_title', cm.video_title,
      'video_kind', cm.video_kind,
      'author_channel_id', cm.author_channel_id,
      'author_name', cm.author_name,
      'text_raw', cm.text_raw,
      'content_hash', cm.content_hash,
      'likes_raw', cm.likes_raw,
      'likes_value', cm.likes_value,
      'published_at', cm.published_at,
      'published_time_raw', cm.published_time_raw,
      'timestamp_precision', cm.timestamp_precision,
      'is_reply', cm.is_reply,
      'parent_comment_id', parent.id::text,
      'parent_source', cm.parent_source,
      'source', cm.source,
      'field_provenance', cm.field_provenance,
      'content_purged_at', cm.content_purged_at,
      'comment_type', an.value,
      'prediction', ap.pred_json,
      'reviews', coalesce(ra.reviews_json, '[]'::json),
      'topic_prediction', atp.topic_pred_json,
      'topic_reviews', coalesce(tra.topic_reviews_json, '[]'::json)
    ) AS row
    FROM recent_comments cm
    JOIN public.videos v ON v.workspace_id = w AND v.id = cm.video_id
    JOIN public.channels ch ON ch.workspace_id = w AND ch.id = v.channel_id
    LEFT JOIN public.comments parent ON parent.workspace_id = w
      AND parent.platform = cm.platform AND parent.external_comment_id = cm.external_parent_id
    LEFT JOIN active_pred ap ON ap.comment_id = cm.id AND ap.content_hash = cm.content_hash
    LEFT JOIN active_tp atp ON atp.comment_id = cm.id AND atp.content_hash = cm.content_hash
    LEFT JOIN reviews_agg ra ON ra.comment_id = cm.id
    LEFT JOIN topic_reviews_agg tra ON tra.comment_id = cm.id
    LEFT JOIN annotations_latest an ON an.comment_id = cm.id
  ) r;

  -- Collection health
  SELECT jsonb_build_object(
    'worker', jsonb_build_object(
      'connected', coalesce((SELECT s.last_seen_at > now() - INTERVAL '3 minutes'
                               FROM public.worker_seen s
                              WHERE s.workspace_id = w), false),
      'last_heartbeat_at', (SELECT s.last_seen_at FROM public.worker_seen s
                             WHERE s.workspace_id = w),
      'busy', coalesce((SELECT count(*) > 0 FROM public.jobs j
                         WHERE j.workspace_id = w
                           AND j.status = 'running'
                           AND j.lease_expires_at > now()), false)),
    'queued_jobs', (SELECT count(*) FROM public.jobs j
                     WHERE j.workspace_id = w AND j.status = 'queued'),
    'last_run', (
      SELECT jsonb_build_object(
        'started_at', s.started_at, 'ended_at', s.ended_at, 'status', s.status,
        'source', s.source, 'error_code', s.error_code,
        'coverage', jsonb_build_object(
          'videos_seen', coalesce((s.coverage_summary->>'videos_seen')::int, 0),
          'comments_collected', coalesce((s.coverage_summary->>'comments_collected')::int, 0),
          'complete', coalesce((s.coverage_summary->>'complete')::boolean, false)))
      FROM public.sync_runs s WHERE s.workspace_id = w AND s.mode = 'collect'
      ORDER BY s.started_at DESC LIMIT 1))
  INTO state;

  RETURN jsonb_build_object(
    'mode', 'live',
    'revision', rev,
    'active_analysis_key', coalesce(active, ''),
    'active_analysis_labels', coalesce((
      SELECT jsonb_agg(k) FROM (
        SELECT DISTINCT k FROM (
          SELECT jsonb_object_keys(p.class_scores) AS k
          FROM public.sentiment_predictions p
          WHERE p.workspace_id = w AND active IS NOT NULL
            AND p.analysis_key = active AND p.status = 'succeeded'
          LIMIT 50
        ) s
      ) s2), '[]'::jsonb),
    'topics', taxonomy,
    'active_topic_key', coalesce(topic_active, ''),
    'plan', private.usage_summary_impl(w),
    'sync', state,
    'comments', rows);
END $function$

CREATE OR REPLACE FUNCTION private.drain_channel_compare(max_workspaces integer DEFAULT 15)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '300s'
AS $function$
declare
  target uuid;
  done int := 0;
  started timestamptz := clock_timestamp();
begin
  for target in
    select d.workspace_id
      from private.channel_compare_dirty d
     group by d.workspace_id
     order by min(d.marked_at), d.workspace_id
     limit greatest(max_workspaces, 0)
  loop
    exit when clock_timestamp() - started > interval '2 minutes';
    begin
      perform private.refresh_channel_compare(target);
      done := done + 1;
    exception when others then
      raise warning 'channel_compare refresh failed for %: %', target, sqlerrm;
    end;
  end loop;
  return done;
end;
$function$

CREATE OR REPLACE FUNCTION private.drain_dashboard_aggregates(max_rows integer DEFAULT 2)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  done int := 0;
begin
  delete from private.dashboard_aggregates_cache
   where requested_at < now() - interval '7 days';

  for r in
    select workspace_id, filter_key, filters
      from private.dashboard_aggregates_cache
     where (computed_at is null or requested_at > computed_at)
       and coalesce(next_attempt_at, '-infinity') <= now()
     order by requested_at
     limit max_rows
       for update skip locked
  loop
    -- compute authorises as the service role; the row was authorised when asked.
    perform set_config('request.jwt.claim.role', 'service_role', true);
    begin
      update private.dashboard_aggregates_cache
         set payload = private.dashboard_aggregates_compute(r.workspace_id, r.filters),
             computed_at = now(), attempts = 0, next_attempt_at = null, last_error = null
       where workspace_id = r.workspace_id and filter_key = r.filter_key;
      done := done + 1;
    exception when others then
      update private.dashboard_aggregates_cache
         set attempts = attempts + 1,
             last_error = sqlstate,
             next_attempt_at = now() + make_interval(secs => least(60 * power(2, attempts), 3600))
       where workspace_id = r.workspace_id and filter_key = r.filter_key;
    end;
  end loop;
  perform set_config('request.jwt.claim.role', '', true);
  return done;
end
$function$

CREATE OR REPLACE FUNCTION private.drain_video_comment_stats(max_videos integer DEFAULT 1000, budget interval DEFAULT '00:00:30'::interval)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target record;
  done int := 0;
  started timestamptz := clock_timestamp();
begin
  if not pg_try_advisory_xact_lock(hashtextextended('video_comment_stats_drain', 0)) then
    return 0;
  end if;

  for target in
    select d.workspace_id, d.video_id
      from private.video_comment_stats_dirty d
     group by d.workspace_id, d.video_id
     order by min(d.marked_at), d.workspace_id, d.video_id
     limit greatest(max_videos, 0)
  loop
    exit when clock_timestamp() - started > budget;
    begin
      delete from private.video_comment_stats_dirty
       where workspace_id = target.workspace_id and video_id = target.video_id;
      if exists (select 1 from public.videos v
                  where v.workspace_id = target.workspace_id and v.id = target.video_id) then
        perform private.refresh_video_comment_stats(jsonb_build_array(jsonb_build_object(
          'workspace_id', target.workspace_id, 'video_id', target.video_id)));
      end if;
      done := done + 1;
    exception when others then
      raise warning 'video_comment_stats drain failed for %/%: %',
        target.workspace_id, target.video_id, sqlerrm;
    end;
  end loop;
  return done;
end;
$function$

CREATE OR REPLACE FUNCTION private.due_videos(w uuid, c uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(
           jsonb_build_object('video_id', v.id, 'external_video_id', v.external_video_id,
                              'title', v.title,
                              'last_seen_comment_count', s.last_seen_comment_count,
                              'reported_comment_count', v.reported_comment_count,
                              'last_collected_at', s.last_collected_at)
           order by s.next_check_at, v.id), '[]'::jsonb)
    from public.video_selections s
    join public.videos v on v.workspace_id = s.workspace_id and v.id = s.video_id
   where s.workspace_id = w and s.channel_id = c
     and s.next_check_at <= now()
     and v.comments_state <> 'disabled';
$function$

CREATE OR REPLACE FUNCTION private.enforce_genre_taxonomy_parent_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  parent_level smallint;
begin
  if new.parent_key is not null then
    select parent.level
      into parent_level
      from public.genre_taxonomy parent
     where parent.version = new.version
       and parent.key = new.parent_key;

    if parent_level is not null and new.level <> parent_level + 1 then
      raise exception 'invalid_genre_parent_level' using errcode = '23514';
    end if;
  end if;

  if exists (
    select 1
      from public.genre_taxonomy child
     where child.version = new.version
       and child.parent_key = new.key
       and child.level <> new.level + 1
  ) then
    raise exception 'invalid_genre_parent_level' using errcode = '23514';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.enqueue_scheduled(w uuid, c uuid, kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j uuid; gap int; latest public.jobs; begin
  if exists(select 1 from public.jobs where workspace_id=w and channel_id=c and type=kind
             and status in ('queued','running')) then return null; end if;
  select * into latest from public.jobs
   where workspace_id=w and channel_id=c and type=kind
   order by created_at desc limit 1;
  -- Blocked until a reset: unblock_due_jobs requeues this same job then. A
  -- fresh job before it would only ask the source the question it has
  -- already answered, and spend quota to hear it.
  if latest.status = 'blocked' and latest.not_before > now() then
    return null; end if;
  -- A job of this kind that just ended badly is not tried again for an hour,
  -- whatever the plan's rate limit says: on a plan with no rate limit the
  -- idle tick re-enqueued a failing collection every time it ran. Measured
  -- from the run's end where one was recorded, else from the job's creation.
  if latest.id is not null
     and latest.status in ('failed','blocked','partial','cancelled')
     and coalesce((select r.ended_at from public.sync_runs r
                    where r.workspace_id = w and r.job_id = latest.id),
                  latest.created_at) > now() - interval '60 minutes' then
    return null; end if;
  gap := private.plan_limit(w, 'sync_interval');
  if gap is not null and gap > 0 and exists(
       select 1 from public.jobs where workspace_id=w and channel_id=c and type=kind
         and created_at > now() - make_interval(mins => gap)) then return null; end if;
  begin
    insert into public.jobs(workspace_id, channel_id, type, dedupe_key)
    values (w, c, kind, kind || '-' || gen_random_uuid()::text) returning id into j;
  exception when unique_violation then return null;
  end;
  return j;
end $function$

CREATE OR REPLACE FUNCTION private.enqueue_sync_impl(w uuid, c uuid, k text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j uuid; gap int; begin
  if not private.has_role(w, array['workspace_owner','analyst']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  if not exists(select 1 from public.channels where workspace_id=w and id=c) then
    raise exception 'invalid_channel' using errcode='23503'; end if;

  -- An idempotent replay is not a new request, so it is answered before the
  -- rate limit rather than being refused for arriving twice.
  select id into j from public.jobs
   where workspace_id=w and dedupe_key=k and channel_id=c and type='collect';
  if j is not null then return j; end if;

  -- Already waiting, or being worked on. That job is the answer; a second one
  -- would collect the same comments twice and say nothing new.
  select id into j from public.jobs
   where workspace_id=w and channel_id=c and type='collect'
     and status in ('queued','running') order by created_at limit 1;
  if j is not null then return j; end if;

  gap := private.plan_limit(w,'sync_interval');
  if gap is not null and gap > 0 and exists(
       select 1 from public.jobs where workspace_id=w and channel_id=c and type='collect'
         and created_at > now() - make_interval(mins => gap)) then
    raise exception 'sync_too_soon' using errcode='53400'; end if;

  begin
    insert into public.jobs(workspace_id,channel_id,type,dedupe_key)
    values (w,c,'collect',k) returning id into j;
  exception when unique_violation then
    -- Two requests raced past the checks above. Whichever index refused this
    -- one, the row that won is the answer to both.
    select id into j from public.jobs
     where workspace_id=w and channel_id=c and type='collect'
       and status in ('queued','running') order by created_at limit 1;
    if j is null then
      select id into j from public.jobs where workspace_id=w and dedupe_key=k; end if;
    if j is null then raise; end if;
  end;
  return j;
end $function$

CREATE OR REPLACE FUNCTION private.genre_classification_key(taxonomy_version integer, model_id text, prompt_version text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select 'genres:v' || taxonomy_version || '+' || model_id || '+' || prompt_version
$function$

CREATE OR REPLACE FUNCTION private.genres_pending(w uuid, c uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with current_taxonomy as (
    select max(version) as version
      from public.genre_taxonomy_versions
  ), recent as (
    select v.id from public.videos v
     where v.workspace_id = w and v.channel_id = c and length(trim(v.title)) > 0
     order by v.published_at desc nulls last, v.id
     limit 50
  )
  select exists (
    select 1 from recent r, current_taxonomy t
     where not exists (
       select 1 from public.video_genre_predictions p
        where p.workspace_id = w and p.video_id = r.id
          and p.classification_key like 'genres:v' || t.version::text || '+%'
          and p.status in ('succeeded','skipped','unsupported')
     )
  )
$function$

CREATE OR REPLACE FUNCTION private.grant_default_plan(w uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (select 1 from public.plans where key = 'free') then return; end if;
  insert into public.subscriptions(workspace_id, plan_key, status, period_start, period_end)
  values (w, 'free', 'active', now(), now() + interval '100 years')
  on conflict (workspace_id) do nothing;
end $function$

CREATE OR REPLACE FUNCTION private.grant_pilot_plan(w uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  -- Nothing to grant if the operator has not defined the plan. A missing plan
  -- row is a deployment that is not finished, and inventing allowances here
  -- would hide that.
  if not exists (select 1 from public.plans where key = 'pilot') then return; end if;
  insert into public.subscriptions(workspace_id, plan_key, status, period_start, period_end)
  values (w, 'pilot', 'active', now(), now() + interval '90 days')
  on conflict (workspace_id) do nothing;
end $function$

CREATE OR REPLACE FUNCTION private.grant_units(w uuid, kind text, units integer, source text, provider_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sub record; g uuid; begin
  select s.period_end into sub from public.subscriptions s where s.workspace_id = private.billing_root(w);
  if not found then raise exception 'no_active_plan' using errcode='42501'; end if;
  insert into public.usage_grants(workspace_id, kind, units, expires_at, source, provider_ref)
  values (w, kind, units, sub.period_end + interval '30 days', source, provider_ref)
  -- By constraint name: inside plpgsql the column names here are also the
  -- parameter names, and a bare column list would be ambiguous.
  on conflict on constraint usage_grants_source_provider_ref_key do nothing returning id into g;
  if g is null then select id into g from public.usage_grants where usage_grants.source = grant_units.source and usage_grants.provider_ref = grant_units.provider_ref; end if;
  return g;
end $function$

CREATE OR REPLACE FUNCTION private.granted_units(w uuid, kind text)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(sum(g.units), 0)::bigint
    from public.usage_grants g
   where g.kind = granted_units.kind and g.expires_at > now()
     and g.workspace_id in (select s.workspace_id from public.subscriptions s
                            where coalesce(s.billing_workspace_id, s.workspace_id) = private.billing_root(w));
$function$

CREATE OR REPLACE FUNCTION private.has_due_videos(w uuid, c uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select exists (
    select 1
      from public.video_selections s
      join public.videos v on v.workspace_id = s.workspace_id and v.id = s.video_id
     where s.workspace_id = w and s.channel_id = c
       and s.next_check_at <= now()
       and v.comments_state <> 'disabled'
  );
$function$

CREATE OR REPLACE FUNCTION private.has_role(w uuid, allowed text[] DEFAULT ARRAY['workspace_owner'::text, 'analyst'::text, 'viewer'::text])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and (
    exists(
      select 1 from public.memberships m
      where m.workspace_id = w
        and m.user_id = (select auth.uid())
        and m.role = any(allowed)
    )
    or (
      'viewer' = any(allowed)
      and exists(
        select 1 from private.platform_admins pa
        where pa.user_id = (select auth.uid())
      )
    )
  );
$function$

CREATE OR REPLACE FUNCTION private.heartbeat(j uuid, t uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  update public.jobs
     set heartbeats = heartbeats + 1,
         lease_expires_at = greatest(lease_expires_at, now() + interval '5 minutes')
   where id = j and lease_token = t and status = 'running' and lease_expires_at > now();
  if not found then raise exception 'lease_lost' using errcode='P0001'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.mark_all_channel_compare()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into private.channel_compare_dirty(workspace_id)
  select distinct c.workspace_id from public.channels c;
$function$

CREATE OR REPLACE FUNCTION private.mark_channel_compare_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into private.channel_compare_dirty(workspace_id)
  select distinct n.workspace_id from new_rows n;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.oauth_attach_channel(state_hash text, external_channel text, tokens bytea, key_version text, scopes text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare st record; begin
  select * into st from private.oauth_consume_state(state_hash);
  return private.oauth_attach_channel_for(
    st.user_id, st.workspace_id, st.client_id, external_channel, tokens, key_version, scopes);
end $function$

CREATE OR REPLACE FUNCTION private.oauth_attach_channel_for(u uuid, w uuid, c uuid, external_channel text, tokens bytea, key_version text, scopes text[], channel_handle text DEFAULT NULL::text, channel_title text DEFAULT NULL::text, p_platform text DEFAULT 'youtube'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ch uuid; begin
  if p_platform is null or p_platform not in ('youtube', 'facebook', 'instagram') then
    raise exception 'invalid_platform' using errcode='22023'; end if;
  if p_platform = 'youtube' then
    if external_channel !~ '^UC[A-Za-z0-9_-]{22}$' then
      raise exception 'invalid_channel_id' using errcode='22023'; end if;
  elsif external_channel !~ '^[0-9]{1,64}$' then
    raise exception 'invalid_channel_id' using errcode='22023';
  end if;
  if exists(select 1 from public.channels
            where platform=p_platform and external_channel_id=external_channel
              and status='connected' and workspace_id <> w) then
    raise exception 'channel_already_connected' using errcode='23505'; end if;

  -- A name the provider did not send this time does not erase one it sent
  -- before: a reconnect after a lapsed grant should not cost the reader the label.
  update public.channels set status='connected', client_id=c,
    handle=coalesce(channel_handle, handle),
    title=coalesce(channel_title, title)
  where workspace_id=w and platform=p_platform
    and external_channel_id=external_channel
  returning id into ch;
  if ch is null then
    insert into public.channels(workspace_id,client_id,external_channel_id,status,handle,title,platform)
    values (w, c, external_channel, 'connected', channel_handle, channel_title, p_platform)
    returning id into ch;
  end if;

  -- The grant being stored replaces whatever was live. Retired, not deleted:
  -- the row stays as the record that a connection existed.
  update private.oauth_connections set status='superseded'
  where channel_id=ch and status='connected';

  insert into private.oauth_connections(
    workspace_id,channel_id,connected_by,encrypted_tokens,key_version,granted_scopes,status)
  values (w, ch, u, tokens, key_version, scopes, 'connected');

  perform private.enqueue_scheduled(w, ch, 'discover');
  return ch;
end $function$

CREATE OR REPLACE FUNCTION private.oauth_complete_impl(ticket text, browser_nonce text, choice uuid DEFAULT NULL::uuid)
 RETURNS TABLE(channel_id uuid, code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  pending record;
  picked record;
  attached uuid;
begin
  select p.*,s.user_id,s.workspace_id,s.client_id,s.browser_nonce_hash
    into pending
  from private.oauth_pending p
  join private.oauth_states s on s.id=p.state_id
  where p.ticket_hash=encode(extensions.digest(ticket,'sha256'),'hex')
  for update of p;

  if not found then
    return query select null::uuid,'oauth_binding_mismatch'::text;
    return;
  end if;

  if pending.expires_at<=now()
     or browser_nonce is null
     or encode(extensions.digest(browser_nonce,'sha256'),'hex') is distinct from pending.browser_nonce_hash
     or (select auth.uid()) is distinct from pending.user_id
     or not private.has_role(pending.workspace_id,array['workspace_owner']) then
    -- A refused completion spends the ticket: a coded answer commits the
    -- deletion, where raising would roll it back and leave it replayable.
    delete from private.oauth_pending p where p.id=pending.id;
    return query select null::uuid,'oauth_binding_mismatch'::text;
    return;
  end if;

  if pending.external_channel is null then
    -- Several pages: nothing is attached until the person picks one, and
    -- asking again does not spend the ticket.
    if choice is null then
      return query select null::uuid,'choose_page'::text;
      return;
    end if;
    select c.* into picked from private.oauth_pending_choices c
     where c.id=choice and c.pending_id=pending.id;
    if not found then
      return query select null::uuid,'invalid_choice'::text;
      return;
    end if;
    delete from private.oauth_pending p where p.id=pending.id;
    attached := private.oauth_attach_channel_for(
      pending.user_id,pending.workspace_id,pending.client_id,
      picked.external_channel,picked.encrypted_tokens,pending.key_version,
      pending.granted_scopes,picked.channel_handle,picked.channel_title,
      pending.platform);
    return query select attached,null::text;
    return;
  end if;

  delete from private.oauth_pending p where p.id=pending.id;
  attached := private.oauth_attach_channel_for(
    pending.user_id,pending.workspace_id,pending.client_id,
    pending.external_channel,pending.encrypted_tokens,pending.key_version,
    pending.granted_scopes,pending.channel_handle,pending.channel_title,
    pending.platform);
  return query select attached,null::text;
end $function$

CREATE OR REPLACE FUNCTION private.oauth_consume_state(state_hash text)
 RETURNS TABLE(state_id uuid, user_id uuid, workspace_id uuid, client_id uuid, code_verifier text, browser_nonce_hash text, provider text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  return query
  update private.oauth_states s set consumed_at=now()
  where s.state_hash=oauth_consume_state.state_hash
    and s.consumed_at is null and s.expires_at>now()
  returning s.id,s.user_id,s.workspace_id,s.client_id,s.code_verifier,s.browser_nonce_hash,s.provider;
  if not found then raise exception 'invalid_state' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.oauth_create_pending(pending_state_id uuid, pending_ticket_hash text, pending_external_channel text, pending_tokens bytea, pending_key_version text, pending_scopes text[], pending_channel_handle text DEFAULT NULL::text, pending_channel_title text DEFAULT NULL::text, pending_platform text DEFAULT 'youtube'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if pending_ticket_hash is null or length(pending_ticket_hash) <> 64 then
    raise exception 'invalid_ticket' using errcode='22023'; end if;
  if pending_platform is null or pending_platform not in ('youtube', 'facebook', 'instagram') then
    raise exception 'invalid_platform' using errcode='22023'; end if;
  -- A YouTube channel id is a UC id; a Meta page or account id is numeric.
  if pending_platform = 'youtube' then
    if pending_external_channel !~ '^UC[A-Za-z0-9_-]{22}$' then
      raise exception 'invalid_channel_id' using errcode='22023'; end if;
  elsif pending_external_channel !~ '^[0-9]{1,64}$' then
    raise exception 'invalid_channel_id' using errcode='22023';
  end if;
  if not exists(
    select 1 from private.oauth_states s
    where s.id=pending_state_id and s.consumed_at is not null) then
    raise exception 'invalid_state' using errcode='42501'; end if;
  insert into private.oauth_pending(
    state_id,ticket_hash,external_channel,channel_handle,channel_title,
    encrypted_tokens,key_version,granted_scopes,expires_at,platform)
  values (
    pending_state_id,pending_ticket_hash,pending_external_channel,
    pending_channel_handle,pending_channel_title,pending_tokens,
    pending_key_version,pending_scopes,now()+interval '10 minutes',pending_platform);
end $function$

CREATE OR REPLACE FUNCTION private.oauth_create_pending_choices(pending_state_id uuid, pending_ticket_hash text, pending_key_version text, pending_scopes text[], pending_platform text, choices jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  pending_id uuid;
  choice jsonb;
  n integer := 0;
  external text;
  tokens text;
begin
  if pending_ticket_hash is null or length(pending_ticket_hash) <> 64 then
    raise exception 'invalid_ticket' using errcode='22023'; end if;
  if pending_platform is distinct from 'facebook' then
    raise exception 'invalid_platform' using errcode='22023'; end if;
  if jsonb_typeof(choices) is distinct from 'array'
     or jsonb_array_length(choices) < 1 or jsonb_array_length(choices) > 100 then
    raise exception 'invalid_choices' using errcode='22023'; end if;
  if not exists(
    select 1 from private.oauth_states s
    where s.id=pending_state_id and s.consumed_at is not null) then
    raise exception 'invalid_state' using errcode='42501'; end if;

  insert into private.oauth_pending(
    state_id,ticket_hash,external_channel,channel_handle,channel_title,
    encrypted_tokens,key_version,granted_scopes,expires_at,platform)
  values (
    pending_state_id,pending_ticket_hash,null,null,null,null,
    pending_key_version,pending_scopes,now()+interval '10 minutes',pending_platform)
  returning id into pending_id;

  for choice in select value from jsonb_array_elements(choices) loop
    external := choice->>'external_channel';
    tokens := choice->>'tokens';
    if tokens is null or tokens !~ '^\\x[0-9a-fA-F]{2,}$' then
      raise exception 'invalid_choices' using errcode='22023'; end if;
    if external is null or external !~ '^[0-9]{1,64}$' then
      raise exception 'invalid_channel_id' using errcode='22023'; end if;
    insert into private.oauth_pending_choices(
      pending_id,position,external_channel,channel_handle,channel_title,encrypted_tokens)
    values (
      pending_id, n, external,
      nullif(left(trim(coalesce(choice->>'handle','')),100),''),
      nullif(left(trim(coalesce(choice->>'title','')),200),''),
      decode(substr(tokens,3),'hex'));
    n := n + 1;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION private.oauth_disconnect_impl(w uuid, channel uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.has_role(w, array['workspace_owner']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  if not exists(select 1 from public.channels where workspace_id=w and id=channel) then
    raise exception 'invalid_channel' using errcode='23503'; end if;
  update public.channels set status='disconnected' where id=channel;
  update private.oauth_connections set status='revoked' where channel_id=channel;
  update public.jobs set status='cancelled', error_code='disconnected'
  where channel_id=channel and status in ('queued','running');
end $function$

CREATE OR REPLACE FUNCTION private.oauth_mark_revoked(channel uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  update public.channels set status='reconnect_required' where id=channel;
  update private.oauth_connections set status='reconnect_required' where channel_id=channel;
  update public.jobs set status='cancelled', error_code='connection_revoked'
  where channel_id=channel and status in ('queued','running');
end $function$

CREATE OR REPLACE FUNCTION private.oauth_pending_for(ticket text, browser_nonce text)
 RETURNS private.oauth_pending
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p private.oauth_pending; ok boolean;
begin
  select pe.* into p
  from private.oauth_pending pe
  join private.oauth_states s on s.id=pe.state_id
  where pe.ticket_hash=encode(extensions.digest(ticket,'sha256'),'hex')
    and pe.expires_at>now()
    and browser_nonce is not null
    and encode(extensions.digest(browser_nonce,'sha256'),'hex') = s.browser_nonce_hash
    and (select auth.uid()) = s.user_id
    and private.has_role(s.workspace_id,array['workspace_owner']);
  return p;
end $function$

CREATE OR REPLACE FUNCTION private.oauth_start_impl(w uuid, c uuid, state_hash text, verifier text, browser_nonce_hash text, p_provider text DEFAULT 'google'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.has_role(w, array['workspace_owner']) then
    raise exception 'forbidden' using errcode='42501'; end if;
  if not exists(select 1 from public.clients where workspace_id=w and id=c) then
    raise exception 'invalid_client' using errcode='23503'; end if;
  if state_hash is null or length(state_hash) <> 64 then
    raise exception 'invalid_state' using errcode='22023'; end if;
  if verifier is null or length(verifier) not between 43 and 128
     or verifier !~ '^[A-Za-z0-9._~-]+$' then
    raise exception 'invalid_verifier' using errcode='22023'; end if;
  if browser_nonce_hash is null or length(browser_nonce_hash) <> 64
     or browser_nonce_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_browser_nonce' using errcode='22023'; end if;
  if p_provider is null or p_provider not in ('google', 'facebook', 'instagram') then
    raise exception 'invalid_provider' using errcode='22023'; end if;
  insert into private.oauth_states(
    state_hash,user_id,workspace_id,client_id,expires_at,code_verifier,browser_nonce_hash,provider)
  values (
    state_hash,(select auth.uid()),w,c,now()+interval '10 minutes',verifier,browser_nonce_hash,p_provider);
  return state_hash;
end $function$

CREATE OR REPLACE FUNCTION private.owner_plan_workspace(u uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select w.id from public.workspaces w
  where w.created_by = u order by w.created_at asc limit 1;
$function$

CREATE OR REPLACE FUNCTION private.plan_json(p plans)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'key', p.key, 'segment', p.segment, 'title_ar', p.title_ar, 'title_en', p.title_en,
    'price_monthly_cents', p.price_monthly_cents, 'price_yearly_cents', p.price_yearly_cents,
    'self_serve', p.self_serve, 'provider_prices', p.provider_prices,
    'allow_public_channels', coalesce(p.allow_public_channels, false),
    'backfill_units', case when p.backfill_units is null or p.backfill_units < 0 or p.backfill_units >= 2147483647 then -1 else p.backfill_units end,
    'historical_days_limit', coalesce(p.historical_days_limit, -1),
    'limits', jsonb_build_object(
      'analysis_units', case when p.analysis_units is null or p.analysis_units < 0 or p.analysis_units >= 2147483647 then -1 else p.analysis_units end,
      'topic_units', case when p.topic_units is null or p.topic_units < 0 or p.topic_units >= 2147483647 then -1 else p.topic_units end,
      'insight_reports', coalesce(p.insight_reports, 0),
      'channels', case when p.channels_limit is null or p.channels_limit < 0 or p.channels_limit >= 2147483647 then -1 else p.channels_limit end,
      'members', case when p.members_limit is null or p.members_limit < 0 or p.members_limit >= 2147483647 then -1 else p.members_limit end,
      'workspaces', case when p.workspaces_limit is null or p.workspaces_limit < 0 or p.workspaces_limit >= 2147483647 then -1 else p.workspaces_limit end,
      'live_interval_minutes', coalesce(p.live_interval_minutes, 0)));
$function$

CREATE OR REPLACE FUNCTION private.plan_key_for_price(price_id text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select k from (
    select p.key || ':' || kv.key as k
    from public.plans p, jsonb_each_text(p.provider_prices) kv
    where kv.value = price_id
    union all
    select a.key || ':pack'
    from public.addon_prices a, jsonb_each_text(a.provider_prices) kv
    where kv.value = price_id
  ) found limit 1;
$function$

CREATE OR REPLACE FUNCTION private.plan_limit(w uuid, which text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.plans; BEGIN
 SELECT pl.* INTO p FROM public.subscriptions s JOIN public.plans pl ON pl.key=s.plan_key
 WHERE s.workspace_id=private.billing_root(w) AND s.status IN ('active','past_due');
 IF NOT FOUND THEN RAISE EXCEPTION 'no_active_plan' USING errcode='42501'; END IF;
 RETURN CASE which WHEN 'channels' THEN p.channels_limit WHEN 'members' THEN p.members_limit
 WHEN 'workspaces' THEN p.workspaces_limit WHEN 'sync_interval' THEN p.min_sync_interval_minutes
 WHEN 'live_interval' THEN p.live_interval_minutes WHEN 'catalogue_interval' THEN p.catalogue_interval_minutes
 WHEN 'competitors' THEN p.competitors_limit END;
END $function$

CREATE OR REPLACE FUNCTION private.platform_owner()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select user_id from private.platform_admins order by added_at limit 1;
$function$

CREATE OR REPLACE FUNCTION private.prevent_comment_move()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.video_id is distinct from old.video_id
     or new.workspace_id is distinct from old.workspace_id then
    raise exception 'comments do not move between videos'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.prune_oauth_states(retain interval DEFAULT '7 days'::interval)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare removed integer; pending_removed integer;
begin
  if retain<interval '0' then
    raise exception 'invalid_input' using errcode='22023'; end if;
  delete from private.oauth_pending p where p.expires_at<now();
  get diagnostics pending_removed=row_count;
  delete from private.oauth_states s
  where (s.consumed_at is not null and s.consumed_at<now()-retain)
     or (s.consumed_at is null and s.expires_at<now()-retain);
  get diagnostics removed=row_count;
  return removed+pending_removed;
end $function$

CREATE OR REPLACE FUNCTION private.purge_channel_profile(retain_text interval DEFAULT '30 days'::interval, retain_stats interval DEFAULT '30 days'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE cleared integer;removed integer;competitor_removed integer; BEGIN
 IF retain_text<interval '0' OR retain_stats<interval '0' THEN RAISE EXCEPTION 'invalid_input' USING errcode='22023'; END IF;
 UPDATE public.channels SET description=NULL,keywords=NULL,topic_categories=NULL WHERE profile_observed_at<now()-retain_text AND (description IS NOT NULL OR keywords IS NOT NULL OR topic_categories IS NOT NULL); GET DIAGNOSTICS cleared=row_count;
 DELETE FROM public.channel_stats_daily WHERE observed_at<now()-retain_stats; GET DIAGNOSTICS removed=row_count;
 DELETE FROM public.competitor_stats_daily WHERE observed_at<now()-retain_stats; GET DIAGNOSTICS competitor_removed=row_count;
 UPDATE public.competitor_candidates SET subscriber_count=NULL,subscriber_count_hidden=NULL,view_count=NULL,video_count=NULL,country=NULL,default_language=NULL,topic_categories=NULL,profile_observed_at=NULL WHERE profile_observed_at<now()-retain_text;
 RETURN jsonb_build_object('profiles',cleared,'stats',removed,'competitor_stats',competitor_removed);
END $function$

CREATE OR REPLACE FUNCTION private.purge_comment_text(retain interval DEFAULT '30 days'::interval)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare removed integer;
begin
  if retain < interval '0' then
    raise exception 'invalid_input' using errcode='22023'; end if;
  update public.comments set
    text_raw = null, text_plain = null,
    -- The author is personal data belonging to someone who is not the customer.
    author_name = null, author_channel_id = null,
    likes_raw = null,
    content_purged_at = now()
  where content_purged_at is null and last_seen_at < now() - retain;
  get diagnostics removed = row_count;
  return removed;
end $function$

CREATE OR REPLACE FUNCTION private.purge_foreign_catalogue(p_channel uuid, source_external text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE ch public.channels; foreign_ids uuid[]; n_videos int; n_comments int; BEGIN
  SELECT * INTO ch FROM public.channels WHERE id = p_channel;
  IF ch.id IS NULL THEN
    RAISE EXCEPTION 'invalid_channel' USING errcode='23503'; END IF;
  IF source_external IS NULL OR source_external !~ '^UC[A-Za-z0-9_-]{22}$' THEN
    RAISE EXCEPTION 'invalid_channel_id' USING errcode='22023'; END IF;
  -- The source channel's own rows are its own, wherever they sit.
  IF coalesce(ch.platform, 'youtube') <> 'youtube' OR ch.external_channel_id = source_external THEN
    RETURN jsonb_build_object('videos', 0, 'comments', 0);
  END IF;

  SELECT coalesce(array_agg(v.id), '{}') INTO foreign_ids
    FROM public.videos v
   WHERE v.workspace_id = ch.workspace_id AND v.channel_id = ch.id
     AND EXISTS (
       SELECT 1 FROM public.videos s
         JOIN public.channels sc ON sc.workspace_id = s.workspace_id AND sc.id = s.channel_id
        WHERE sc.platform = 'youtube' AND sc.external_channel_id = source_external
          AND s.platform = 'youtube' AND s.external_video_id = v.external_video_id);
  IF cardinality(foreign_ids) = 0 THEN
    RETURN jsonb_build_object('videos', 0, 'comments', 0);
  END IF;

  PERFORM set_config('app.deleting_workspace', ch.workspace_id::text, true);
  DELETE FROM public.sentiment_predictions WHERE workspace_id = ch.workspace_id AND comment_id IN (
    SELECT id FROM public.comments WHERE workspace_id = ch.workspace_id AND video_id = ANY(foreign_ids));
  DELETE FROM public.topic_predictions WHERE workspace_id = ch.workspace_id AND comment_id IN (
    SELECT id FROM public.comments WHERE workspace_id = ch.workspace_id AND video_id = ANY(foreign_ids));
  DELETE FROM public.comment_reviews WHERE workspace_id = ch.workspace_id AND comment_id IN (
    SELECT id FROM public.comments WHERE workspace_id = ch.workspace_id AND video_id = ANY(foreign_ids));
  DELETE FROM public.topic_reviews WHERE workspace_id = ch.workspace_id AND comment_id IN (
    SELECT id FROM public.comments WHERE workspace_id = ch.workspace_id AND video_id = ANY(foreign_ids));
  DELETE FROM public.comment_annotations WHERE workspace_id = ch.workspace_id AND comment_id IN (
    SELECT id FROM public.comments WHERE workspace_id = ch.workspace_id AND video_id = ANY(foreign_ids));
  DELETE FROM public.comments WHERE workspace_id = ch.workspace_id AND video_id = ANY(foreign_ids);
  GET DIAGNOSTICS n_comments = row_count;
  DELETE FROM public.video_selections WHERE workspace_id = ch.workspace_id AND video_id = ANY(foreign_ids);
  DELETE FROM public.videos WHERE workspace_id = ch.workspace_id AND id = ANY(foreign_ids);
  GET DIAGNOSTICS n_videos = row_count;
  PERFORM set_config('app.deleting_workspace', '', true);
  RETURN jsonb_build_object('videos', n_videos, 'comments', n_comments);
END $function$

CREATE OR REPLACE FUNCTION private.reconcile_all_video_comment_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  workspace record;
  result jsonb;
  workspaces_checked integer := 0;
  videos_checked integer := 0;
  rows_corrected integer := 0;
  drifted jsonb := '[]'::jsonb;
begin
  for workspace in
    select id
    from public.workspaces
    order by id
  loop
    result := private.reconcile_video_comment_stats(workspace.id);
    workspaces_checked := workspaces_checked + 1;
    videos_checked := videos_checked + (result ->> 'videos_checked')::integer;
    rows_corrected := rows_corrected + (result ->> 'rows_corrected')::integer;

    if (result ->> 'rows_corrected')::integer > 0 then
      drifted := drifted || jsonb_build_array(result);
    end if;
  end loop;

  return jsonb_build_object(
    'workspaces_checked', workspaces_checked,
    'videos_checked', videos_checked,
    'rows_corrected', rows_corrected,
    'drifted', drifted
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.reconcile_video_comment_stats(w uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET enable_nestloop TO 'off'
AS $function$
declare
  pairs jsonb := '[]'::jsonb;
  videos_checked integer := 0;
  rows_corrected integer := 0;
begin
  with exact_counts as (
    select
      v.id as video_id,
      v.workspace_id,
      count(c.id)::integer as total_comments,
      count(c.id) filter (
        where exists (
          select 1
          from public.sentiment_predictions sp
          where sp.comment_id = c.id
            and sp.workspace_id = c.workspace_id
            and sp.status = 'succeeded'
        )
      )::integer as analysed_comments
    from public.videos v
    left join public.comments c
      on c.video_id = v.id
     and c.workspace_id = v.workspace_id
    where v.workspace_id = w
    group by v.id, v.workspace_id
  ), drift as (
    select
      e.video_id,
      e.workspace_id,
      e.total_comments,
      e.analysed_comments,
      coalesce(s.total, 0) as stored_total_comments,
      coalesce(s.analysed, 0) as stored_analysed_comments
    from exact_counts e
    left join private.video_comment_stats s
      on s.video_id = e.video_id
     and s.workspace_id = e.workspace_id
  )
  select
    count(*)::integer,
    count(*) filter (
      where stored_total_comments is distinct from total_comments
         or stored_analysed_comments is distinct from analysed_comments
    )::integer,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'video_id', video_id,
          'workspace_id', workspace_id
        )
      ) filter (
        where stored_total_comments is distinct from total_comments
           or stored_analysed_comments is distinct from analysed_comments
      ),
      '[]'::jsonb
    )
  into videos_checked, rows_corrected, pairs
  from drift;

  if rows_corrected > 0 then
    perform private.refresh_video_comment_stats(pairs);
  end if;

  return jsonb_build_object(
    'workspace_id', w,
    'videos_checked', videos_checked,
    'rows_corrected', rows_corrected
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.record_admin_digest()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '120s'
AS $function$
begin
  insert into private.admin_digests(day, recorded_at, body)
  values ((now() at time zone 'UTC')::date, now(), private.build_admin_digest())
  on conflict (day) do update
    set recorded_at = excluded.recorded_at, body = excluded.body;
  delete from private.admin_digests
   where day < (now() at time zone 'UTC')::date - 30;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_channel_compare(w uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ch record;
begin
  perform pg_advisory_xact_lock(hashtextextended('channel_compare:' || w::text, 0));
  delete from private.channel_compare_dirty where workspace_id = w;
  for ch in select c.id from public.channels c where c.workspace_id = w order by c.id loop
    perform private.refresh_channel_compare_channel(w, ch.id);
  end loop;
  insert into private.channel_compare_refreshed(workspace_id, refreshed_at)
  values (w, now())
  on conflict (workspace_id) do update set refreshed_at = excluded.refreshed_at;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_channel_compare_channel(w uuid, p_channel uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET enable_nestloop TO 'off'
AS $function$
declare
  topic_active text;
  since date := (now() at time zone 'UTC')::date - 35;
begin
  perform pg_advisory_xact_lock(
    hashtextextended('channel_compare:' || w::text || ':' || p_channel::text, 0));

  select ws.active_topic_key into topic_active
    from public.workspaces ws where ws.id = w;

  delete from private.channel_compare_cells
   where workspace_id = w and channel_id = p_channel;

  insert into private.channel_compare_cells(
    workspace_id, channel_id, day, topic_key,
    comments, analysed, positive, negative, neutral, mixed)
  with ch as (
    select c.id, c.external_channel_id, c.active_analysis_key
      from public.channels c
     where c.workspace_id = w and c.id = p_channel
  ),
  audience as (
    select v.channel_id, cm.id, cm.content_hash, ch.active_analysis_key,
           case when cm.published_at >= since
                then (cm.published_at at time zone 'UTC')::date end as day
      from public.videos v
      join ch on ch.id = v.channel_id
      join public.comments cm on cm.workspace_id = v.workspace_id and cm.video_id = v.id
     where v.workspace_id = w and v.channel_id = p_channel
       and not coalesce(cm.author_channel_id = ch.external_channel_id, false)
  ),
  rev as (
    select distinct on (r.comment_id) r.comment_id, r.content_hash, r.label
      from public.comment_reviews r
     where r.workspace_id = w and r.origin = 'human'
     order by r.comment_id, r.created_at desc
  ),
  trev as (
    select distinct on (r.comment_id) r.comment_id, r.content_hash, r.topic_key
      from public.topic_reviews r
     where r.workspace_id = w and r.origin = 'human'
     order by r.comment_id, r.created_at desc
  ),
  ev as (
    select a.channel_id, a.day,
           case when r.content_hash = a.content_hash then r.label else p.label end as label,
           case when t.content_hash = a.content_hash then t.topic_key else tp.topic_key end as topic
      from audience a
      left join rev r on r.comment_id = a.id
      left join public.sentiment_predictions p
        on p.workspace_id = w and p.comment_id = a.id
       and p.content_hash = a.content_hash
       and p.analysis_key = a.active_analysis_key
       and p.status = 'succeeded'
      left join trev t on t.comment_id = a.id
      left join public.topic_predictions tp
        on tp.workspace_id = w and tp.comment_id = a.id
       and tp.content_hash = a.content_hash
       and tp.classification_key = topic_active
       and tp.status = 'succeeded'
  )
  select w, ev.channel_id, ev.day, ev.topic,
         count(*), count(ev.label),
         count(*) filter (where ev.label = 'positive'),
         count(*) filter (where ev.label = 'negative'),
         count(*) filter (where ev.label = 'neutral'),
         count(*) filter (where ev.label = 'mixed')
    from ev
   group by ev.channel_id, ev.day, ev.topic;

  insert into private.channel_compare_units as u(workspace_id, channel_id, refreshed_at)
  values (w, p_channel, now())
  on conflict (workspace_id, channel_id) do update
    set refreshed_at = now(), dirty_since = null, attempts = 0,
        next_attempt_at = null, last_error = null, last_error_at = null;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_channel_genres(w uuid, c uuid, p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v int;
begin
 select max(taxonomy_version) into v from public.video_genre_predictions p
  join public.videos vd on vd.workspace_id=p.workspace_id and vd.id=p.video_id
 where p.workspace_id=w and vd.channel_id=c and p.classification_key=p_key and p.status='succeeded';
 delete from public.channel_genres where workspace_id=w and channel_id=c and classification_key=p_key;
 if v is null then return; end if;
 with recent as (
  select p.genre_key,p.video_id,vd.published_at,vd.view_count,
         ln(1+coalesce(vd.view_count,0)::numeric)+1 as popularity,
         case when vd.published_at is null then 0.5 else power(0.5::numeric,
           greatest(0,extract(epoch from (now()-vd.published_at))/86400)/90) end as recency
   from public.video_genre_predictions p join public.videos vd
    on vd.workspace_id=p.workspace_id and vd.id=p.video_id
  where p.workspace_id=w and vd.channel_id=c and p.classification_key=p_key
    and p.taxonomy_version=v and p.status='succeeded'
  order by vd.published_at desc nulls last,vd.id limit 50
 ), enough as (select count(distinct video_id) n from recent), rolled as (
  select g.version,g.key,g.level,r.video_id,r.popularity*r.recency raw_weight
   from recent r join public.genre_taxonomy leaf on leaf.version=v and leaf.key=r.genre_key
   join public.genre_taxonomy g on g.version=leaf.version and
    (g.key=leaf.key or g.key=leaf.parent_key or g.key=(select p.parent_key from public.genre_taxonomy p where p.version=leaf.version and p.key=leaf.parent_key))
 ), agg as (
  select version,key,level,count(distinct video_id)::int videos,sum(raw_weight) raw_weight
    from rolled group by version,key,level
 ), normalized as (
  select a.*,sum(raw_weight) over(partition by level) total from agg a
 )
 insert into public.channel_genres(workspace_id,channel_id,classification_key,taxonomy_version,genre_key,level,weight,videos,computed_at)
 select w,c,p_key,n.version,n.key,n.level,
        case when row_number() over(partition by n.level order by n.raw_weight desc,n.key)=1
          then (1 - coalesce(sum(round((n.raw_weight/n.total)::numeric,4)) over(partition by n.level
                    order by n.raw_weight desc,n.key rows between 1 following and unbounded following),0))::numeric(5,4)
          else round((raw_weight/total)::numeric,4) end,
        videos,now()
 from normalized n, enough where enough.n>=5;
end $function$

CREATE OR REPLACE FUNCTION private.refresh_video_comment_stats(pairs jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  deleting text := nullif(current_setting('app.deleting_workspace', true), '');
begin
  if deleting is not null then
    select coalesce(jsonb_agg(e), '[]'::jsonb) into pairs
    from jsonb_array_elements(coalesce(pairs, '[]'::jsonb)) e
    where e->>'workspace_id' is distinct from deleting;
    if pairs = '[]'::jsonb then return; end if;
  end if;

  insert into private.video_comment_stats(workspace_id, video_id, total, analysed)
  select distinct p.workspace_id, p.video_id, 0, 0
  from jsonb_to_recordset(coalesce(pairs, '[]'::jsonb))
    as p(workspace_id uuid, video_id uuid)
  on conflict (workspace_id, video_id) do nothing;

  -- Serialize recomputes for each video. The following UPDATE is a separate
  -- statement, so READ COMMITTED gives it a fresh snapshot after any lock
  -- holder commits. Stable ordering prevents multi-video statements from
  -- taking the same row locks in conflicting orders.
  perform 1
  from private.video_comment_stats s
  join jsonb_to_recordset(coalesce(pairs, '[]'::jsonb))
    as p(workspace_id uuid, video_id uuid)
    on p.workspace_id = s.workspace_id
   and p.video_id = s.video_id
  order by s.workspace_id, s.video_id
  for update of s;

  with affected as (
    select distinct p.workspace_id, p.video_id
    from jsonb_to_recordset(coalesce(pairs, '[]'::jsonb))
      as p(workspace_id uuid, video_id uuid)
  ), counts as (
    select
      p.workspace_id,
      p.video_id,
      count(c.id)::int as total,
      count(c.id) filter (
        where exists (
          select 1
          from public.sentiment_predictions sp
          where sp.workspace_id = c.workspace_id
            and sp.comment_id = c.id
            and sp.status = 'succeeded'
        )
      )::int as analysed
    from affected p
    left join public.comments c
      on c.workspace_id = p.workspace_id
     and c.video_id = p.video_id
    group by p.workspace_id, p.video_id
  )
  update private.video_comment_stats s
  set total = counts.total,
      analysed = counts.analysed
  from counts
  where s.workspace_id = counts.workspace_id
    and s.video_id = counts.video_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_video_comment_stats_after_comment_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into private.video_comment_stats_dirty(workspace_id, video_id)
  select distinct o.workspace_id, o.video_id
    from old_comments o
   where o.workspace_id::text is distinct from
         nullif(current_setting('app.deleting_workspace', true), '');
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_video_comment_stats_after_comment_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into private.video_comment_stats_dirty(workspace_id, video_id)
  select distinct n.workspace_id, n.video_id
    from new_comments n
   where n.workspace_id::text is distinct from
         nullif(current_setting('app.deleting_workspace', true), '');
  return null;
end;
$function$

